// ─── Navigation ───
function applyUserRole() {
  const role = sessionStorage.getItem("fms_user_role");
  const ids = ["nav-dashboard", "nav-vehicles", "nav-bikes", "nav-drivers", "nav-monthlyreport", "nav-departments", "nav-tokentax", "nav-settings"];
  ids.forEach(id => {
    const el = document.getElementById(id);
    if (el) {
      if (role === "user") { el.style.display = "none"; }
      else { el.style.display = ""; }
    }
  });
}

function navigate(page) {
  const role = sessionStorage.getItem("fms_user_role");
  if (role === "user" && !["fuel", "maintenance", "ledger", "bills", "mtag"].includes(page)) {
     showToast("Access Denied for regular user", "error");
     if (!document.querySelector(".page.active")) navigate("fuel");
     return;
  }
  document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
  document.querySelectorAll('.nav-item').forEach(n => n.classList.remove('active'));
  document.getElementById('page-' + page).classList.add('active');
  const navEl = document.getElementById('nav-' + page);
  if (navEl) navEl.classList.add('active');
  document.getElementById('topbarTitle').textContent = {
    dashboard: 'Dashboard', vehicles: 'Vehicles',
    drivers: 'Drivers', maintenance: 'Maintenance',
    fuel: 'Fuel Log', reports: 'Reports',
    departments: 'Departments', bills: 'Bill View',
    settings: 'System Settings', tokentax: 'Token & Tax', mtag: 'M-Tag',
    ledger: 'Accounts / Ledger', monthlyreport: 'Monthly Report'
  }[page] || page;
  renderPage(page);
  // Close sidebar on mobile
  if (window.innerWidth <= 900) {
    document.getElementById('sidebar').classList.remove('open');
  }
}

function renderPage(page) {
  if (page === 'dashboard')   renderDashboard();
  if (page === 'vehicles')    renderVehicles();
  if (page === 'bikes')       renderBikes();
  if (page === 'drivers')     renderDrivers();
  if (page === 'maintenance') renderMaintenance();
  if (page === 'fuel')        renderFuel();
  if (page === 'reports')     renderReports();
  if (page === 'bills') {
    renderBills();
    renderDownloadHistory();
  }
  if (page === 'departments') renderDepartments();
  if (page === 'settings')    renderSettings();
  if (page === 'tokentax')    renderTokenTax();
  if (page === 'mtag')        renderMTag();
  if (page === 'ledger')         renderLedger();
  if (page === 'monthlyreport')  renderMonthlyReportPage();
  renderSidebarDeptVehicles();
}

// ─── MONTHLY REPORT PAGE ───
function renderMonthlyReportPage() {
  const MONTH_NAMES = ['January','February','March','April','May','June','July','August','September','October','November','December'];
  const SHORT_MONTHS = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];

  // Build list of available months from fuel + maintenance
  const monthSet = new Set();
  (state.fuel || []).forEach(f => { if (f.date) { const d = new Date(f.date); monthSet.add(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`); } });
  (state.maintenance || []).forEach(m => { if (m.date) { const d = new Date(m.date); monthSet.add(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`); } });

  const allMonths = [...monthSet].sort().reverse();
  const sel = document.getElementById('monthlyReportMonthSelect');
  if (!sel) return;

  const prev = sel.value;
  sel.innerHTML = allMonths.map(m => {
    const [y, mo] = m.split('-');
    return `<option value="${m}" ${m === prev ? 'selected' : ''}>${MONTH_NAMES[parseInt(mo)-1]} ${y}</option>`;
  }).join('');

  // Auto-select current month if no previous selection
  if (!prev || !allMonths.includes(prev)) {
    const now = new Date();
    const cur = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`;
    if (allMonths.includes(cur)) sel.value = cur;
    else if (allMonths.length > 0) sel.value = allMonths[0];
  }

  const selectedKey = sel.value;
  if (!selectedKey) {
    document.getElementById('monthlyReportVehicleBody').innerHTML = `<tr><td colspan="8" style="text-align:center;padding:30px;color:var(--text-muted);">No data available</td></tr>`;
    return;
  }

  const [selYear, selMonth] = selectedKey.split('-').map(Number);
  const search = (document.getElementById('m-rep-vehicle-search')?.value || '').toLowerCase();

  const [mo, yr] = [selMonth-1, selYear];
  const titleEl = document.getElementById('m-rep-table-title');
  if (titleEl) titleEl.textContent = `🚗 Vehicle-wise Expenditure — ${MONTH_NAMES[mo]} ${yr}`;

  // Aggregate fuel per vehicle for selected month
  const fuelByVehicle = {};
  (state.fuel || []).forEach(f => {
    if (!f.date) return;
    const d = new Date(f.date);
    if (d.getFullYear() !== yr || d.getMonth() !== mo) return;
    const vObj = state.vehicles.find(v => v.id === f.vehicle || `${v.name} (${v.plate})` === f.vehicle || v.plate === f.vehicle);
    const vId = vObj ? vObj.id : (f.vehicle || 'unknown');
    if (!fuelByVehicle[vId]) fuelByVehicle[vId] = { litres: 0, cost: 0, vObj };
    fuelByVehicle[vId].litres += Number(f.litres) || 0;
    fuelByVehicle[vId].cost   += Number(f.cost) || 0;
    if (!fuelByVehicle[vId].vObj && vObj) fuelByVehicle[vId].vObj = vObj;
  });

  // Aggregate maintenance per vehicle for selected month
  const maintByVehicle = {};
  (state.maintenance || []).forEach(m => {
    if (!m.date) return;
    const d = new Date(m.date);
    if (d.getFullYear() !== yr || d.getMonth() !== mo) return;
    const vObj = state.vehicles.find(v => v.id === m.vehicle || `${v.name} (${v.plate})` === m.vehicle || v.plate === m.vehicle);
    const vId = vObj ? vObj.id : (m.vehicle || 'unknown');
    if (!maintByVehicle[vId]) maintByVehicle[vId] = { cost: 0, vObj };
    maintByVehicle[vId].cost += Number(m.cost) || 0;
    if (!maintByVehicle[vId].vObj && vObj) maintByVehicle[vId].vObj = vObj;
  });

  // Merge all vehicle IDs
  const allVehicleIds = new Set([...Object.keys(fuelByVehicle), ...Object.keys(maintByVehicle)]);

  let rows = [];
  allVehicleIds.forEach(vId => {
    const fuel = fuelByVehicle[vId] || { litres: 0, cost: 0 };
    const maint = maintByVehicle[vId] || { cost: 0 };
    const vObj = fuel.vObj || maint.vObj || state.vehicles.find(v => v.id === vId);
    const plate = vObj ? vObj.plate : vId;
    const model = vObj ? vObj.name : '—';
    const driver = vObj ? getDriverName(vObj.driver) : '—';

    // Fuel average from state.fuel for this month for this vehicle
    const fuelEntries = (state.fuel || []).filter(f => {
      if (!f.date) return false;
      const d = new Date(f.date);
      if (d.getFullYear() !== yr || d.getMonth() !== mo) return false;
      const fVObj = state.vehicles.find(v => v.id === f.vehicle || `${v.name} (${v.plate})` === f.vehicle);
      const fVId = fVObj ? fVObj.id : f.vehicle;
      return fVId === vId;
    });
    const avgVals = fuelEntries.filter(f => f.fuelAverage && f.fuelAverage !== 'First' && f.fuelAverage !== '—');
    let avgDisp = '—';
    if (avgVals.length > 0) {
      const nums = avgVals.map(f => parseFloat(f.fuelAverage));
      const avg = nums.reduce((a,b)=>a+b,0) / nums.length;
      avgDisp = avg.toFixed(2) + ' km/L';
    }

    rows.push({ plate, model, driver, fuelLitres: fuel.litres, fuelCost: fuel.cost, maintCost: maint.cost, avgDisp });
  });

  // Apply search filter
  if (search) {
    rows = rows.filter(r => r.plate.toLowerCase().includes(search) || r.model.toLowerCase().includes(search) || r.driver.toLowerCase().includes(search));
  }

  // Sort by total cost descending
  rows.sort((a, b) => (b.fuelCost + b.maintCost) - (a.fuelCost + a.maintCost));

  // Summary totals
  let totLitres = 0, totFuel = 0, totMaint = 0;
  rows.forEach(r => { totLitres += r.fuelLitres; totFuel += r.fuelCost; totMaint += r.maintCost; });

  // Update stat cards
  const setEl = (id, val) => { const el = document.getElementById(id); if(el) el.textContent = val; };
  setEl('m-rep-fuel-litres', totLitres.toFixed(2) + ' L');
  setEl('m-rep-fuel-cost', fmtPKR(totFuel));
  setEl('m-rep-maint-cost', fmtPKR(totMaint));
  setEl('m-rep-total-cost', fmtPKR(totFuel + totMaint));

  const tbody = document.getElementById('monthlyReportVehicleBody');
  const tfoot = document.getElementById('monthlyReportVehicleFoot');
  if (!tbody) return;

  if (rows.length === 0) {
    tbody.innerHTML = `<tr><td colspan="8" style="text-align:center;padding:30px;color:var(--text-muted);">No data found for selected month</td></tr>`;
    if (tfoot) tfoot.innerHTML = '';
    return;
  }

  tbody.innerHTML = rows.map((r, i) => {
    const total = r.fuelCost + r.maintCost;
    const driverDisplay = (r.driver && r.driver !== '—' && !/^[a-z0-9_]{10,}$/i.test(r.driver)) ? r.driver : '—';
    return `<tr>
      <td style="text-align:center; font-weight:700;">${i+1}</td>
      <td>
        <strong style="font-size:0.92rem; color:#1e3a8a; display:block;">${r.plate}</strong>
        <div style="font-size:0.8rem; color:#64748b; margin-top:2px;">${r.model}</div>
      </td>
      <td><strong>${driverDisplay}</strong></td>
      <td style="color:#4f46e5; font-weight:700; text-align:right;">${r.fuelLitres > 0 ? r.fuelLitres.toFixed(2) + ' L' : '—'}</td>
      <td style="color:#2563eb; font-weight:700; text-align:right;">${r.fuelCost > 0 ? fmtPKR(r.fuelCost) : '—'}</td>
      <td style="color:#ea580c; font-weight:700; text-align:right;">${r.maintCost > 0 ? fmtPKR(r.maintCost) : '—'}</td>
      <td style="color:#047857; font-weight:800; font-size:1rem; text-align:right; background:rgba(16,185,129,0.1); border-left:1px solid rgba(16,185,129,0.2); border-right:1px solid rgba(16,185,129,0.2);">${fmtPKR(total)}</td>
      <td class="fuel-avg-col" style="text-align:center;"><span style="background:rgba(16,185,129,0.12); padding:3px 10px; border-radius:20px; font-size:0.8rem; font-weight:700; color:#047857;">${r.avgDisp}</span></td>
    </tr>`;
  }).join('');

  if (tfoot) {
    tfoot.innerHTML = `<tr style="background:#f8fafc; border-top:2px solid #0f172a; border-bottom:2px solid #0f172a;">
      <td colspan="3" style="padding:12px 10px; text-align:right; font-weight:900; font-size:1.02rem; color:#0f172a;">GRAND TOTAL</td>
      <td style="padding:12px 10px; color:#4f46e5; font-weight:800; text-align:right;">${totLitres.toFixed(2)} L</td>
      <td style="padding:12px 10px; color:#2563eb; font-weight:800; text-align:right;">${fmtPKR(totFuel)}</td>
      <td style="padding:12px 10px; color:#ea580c; font-weight:800; text-align:right;">${fmtPKR(totMaint)}</td>
      <td style="padding:12px 10px; color:#047857; font-weight:900; font-size:1.15rem; text-align:right; background:#dcfce7; border-left:1px solid #86efac; border-right:1px solid #86efac;">${fmtPKR(totFuel+totMaint)}</td>
      <td class="fuel-avg-col" style="padding:12px 10px; text-align:center;">—</td>
    </tr>`;
  }

  // Also render fuel details tab and maintenance details tab
  renderFuelDetailsTab(selectedKey, selYear, selMonth);
  renderMaintDetailsTab(selectedKey, selYear, selMonth);
}

// ─── Tab Switcher ───
function switchMonthlyTab(tab) {
  const tabSummary     = document.getElementById('tabSummary');
  const tabFuelDetail  = document.getElementById('tabFuelDetail');
  const tabMaintDetail = document.getElementById('tabMaintDetail');
  const btnSummary     = document.getElementById('tabBtnSummary');
  const btnFuelDetail  = document.getElementById('tabBtnFuelDetail');
  const btnMaintDetail = document.getElementById('tabBtnMaintDetail');

  const setBtnActive = (btn, active) => {
    if (!btn) return;
    if (active) {
      btn.className = 'btn-primary';
      btn.style.background = '#1e3a8a';
      btn.style.borderColor = '#1e3a8a';
    } else {
      btn.className = 'btn-secondary';
      btn.style.background = '';
      btn.style.borderColor = '';
    }
  };

  if (tabSummary)     tabSummary.style.display     = tab === 'summary' ? 'block' : 'none';
  if (tabFuelDetail)  tabFuelDetail.style.display  = tab === 'fueldetail' ? 'block' : 'none';
  if (tabMaintDetail) tabMaintDetail.style.display = tab === 'maintdetail' ? 'block' : 'none';

  setBtnActive(btnSummary, tab === 'summary');
  setBtnActive(btnFuelDetail, tab === 'fueldetail');
  setBtnActive(btnMaintDetail, tab === 'maintdetail');
}

// ─── Render Fuel Details Tab ───
function renderFuelDetailsTab(selectedKey, yr, mo) {
  const MONTH_NAMES = ['January','February','March','April','May','June','July','August','September','October','November','December'];
  const container = document.getElementById('fuelDetailsContainer');
  const label     = document.getElementById('fuelDetailMonthLabel');
  if (!container) return;

  if (label) label.textContent = `${MONTH_NAMES[mo - 1]} ${yr}`;

  // Gather all fuel entries for this month
  const monthFuelEntries = (state.fuel || []).filter(f => {
    if (!f.date) return false;
    const d = new Date(f.date);
    return d.getFullYear() === yr && (d.getMonth() + 1) === mo;
  });

  if (monthFuelEntries.length === 0) {
    container.innerHTML = `<div style="text-align:center; padding:40px; color:var(--text-muted); font-size:0.95rem;">No fuel entries found for this month.</div>`;
    return;
  }

  // Group fuel entries by vehicle
  const byVehicle = {};
  monthFuelEntries.forEach(f => {
    const vObj = state.vehicles.find(v => v.id === f.vehicle || `${v.name} (${v.plate})` === f.vehicle || v.plate === f.vehicle);
    const vId  = vObj ? vObj.id : (f.vehicle || 'unknown');
    const plate = vObj ? vObj.plate : (f.vehicle || '—');
    const model = vObj ? vObj.name  : '—';
    if (!byVehicle[vId]) byVehicle[vId] = { plate, model, entries: [] };
    byVehicle[vId].entries.push(f);
  });

  // Sort each vehicle's entries by date ascending
  Object.values(byVehicle).forEach(vData => {
    vData.entries.sort((a, b) => new Date(a.date) - new Date(b.date));
  });

  // Sort vehicles by plate
  const sortedVehicles = Object.values(byVehicle).sort((a, b) => a.plate.localeCompare(b.plate));

  let html = '';
  sortedVehicles.forEach(vData => {
    const totalLitres = vData.entries.reduce((s, f) => s + (Number(f.litres) || 0), 0);
    const totalCost   = vData.entries.reduce((s, f) => s + (Number(f.cost)   || 0), 0);

    const rows = vData.entries.map((f, idx) => `
      <tr style="background:${idx % 2 === 0 ? '#ffffff' : '#f8fafc'};">
        <td style="padding:9px 12px; border:1px solid #e2e8f0; color:#64748b; font-size:0.85rem;">${idx + 1}</td>
        <td style="padding:9px 12px; border:1px solid #e2e8f0; font-weight:600; color:#0f172a;">${formatDate(f.date)}</td>
        <td style="padding:9px 12px; border:1px solid #e2e8f0; color:#4f46e5; font-weight:700; text-align:right;">${Number(f.litres).toFixed(2)} L</td>
        <td style="padding:9px 12px; border:1px solid #e2e8f0; color:#475569; font-size:0.85rem; text-align:right;">${Number(f.rate || 0).toFixed(2)}</td>
        <td style="padding:9px 12px; border:1px solid #e2e8f0; color:#2563eb; font-weight:700; text-align:right;">${fmtPKR(f.cost)}</td>
        <td style="padding:9px 12px; border:1px solid #e2e8f0; color:#475569; font-size:0.85rem;">${f.fuelType || 'Petrol'}</td>
        <td style="padding:9px 12px; border:1px solid #e2e8f0; color:#047857; font-size:0.83rem;">${(f.pumpName || '—')}</td>
      </tr>
    `).join('');

    html += `
      <div class="fuel-detail-vehicle-block" data-plate="${vData.plate.toLowerCase()} ${vData.model.toLowerCase()}" style="margin-bottom:28px;">
        <div style="display:flex; align-items:center; gap:12px; margin-bottom:10px;">
          <span style="background:#1e3a8a; color:#fff; font-weight:800; font-size:0.85rem; padding:4px 14px; border-radius:20px;">🚗 ${vData.plate}</span>
          <span style="color:#64748b; font-size:0.85rem; font-weight:600;">${vData.model}</span>
          <span style="margin-left:auto; background:#dcfce7; color:#047857; font-weight:800; font-size:0.85rem; padding:4px 14px; border-radius:20px;">Total: ${fmtPKR(totalCost)} · ${totalLitres.toFixed(2)} L</span>
        </div>
        <div style="overflow-x:auto; border-radius:10px; border:1px solid #e2e8f0; box-shadow:0 1px 4px rgba(0,0,0,0.05);">
          <table style="width:100%; border-collapse:collapse; font-size:0.88rem;">
            <thead>
              <tr style="background:#f1f5f9;">
                <th style="padding:9px 12px; text-align:left; border:1px solid #e2e8f0; color:#64748b; font-size:0.8rem; font-weight:700;">#</th>
                <th style="padding:9px 12px; text-align:left; border:1px solid #e2e8f0; color:#1e3a8a; font-weight:700;">DATE</th>
                <th style="padding:9px 12px; text-align:right; border:1px solid #e2e8f0; color:#4f46e5; font-weight:700;">LITRES</th>
                <th style="padding:9px 12px; text-align:right; border:1px solid #e2e8f0; color:#64748b; font-weight:700;">RATE (PKR)</th>
                <th style="padding:9px 12px; text-align:right; border:1px solid #e2e8f0; color:#2563eb; font-weight:700;">AMOUNT (PKR)</th>
                <th style="padding:9px 12px; text-align:left; border:1px solid #e2e8f0; color:#64748b; font-weight:700;">FUEL TYPE</th>
                <th style="padding:9px 12px; text-align:left; border:1px solid #e2e8f0; color:#64748b; font-weight:700;">PUMP STATION</th>
              </tr>
            </thead>
            <tbody>
              ${rows}
            </tbody>
            <tfoot>
              <tr style="background:#e0f2fe; font-weight:800; border-top:2px solid #0f172a;">
                <td colspan="2" style="padding:10px 12px; border:1px solid #e2e8f0; text-align:right; color:#0f172a; font-size:0.9rem;">TOTAL</td>
                <td style="padding:10px 12px; border:1px solid #e2e8f0; text-align:right; color:#4f46e5;">${totalLitres.toFixed(2)} L</td>
                <td style="padding:10px 12px; border:1px solid #e2e8f0;"></td>
                <td style="padding:10px 12px; border:1px solid #e2e8f0; text-align:right; color:#047857; font-size:1rem;">${fmtPKR(totalCost)}</td>
                <td colspan="2" style="padding:10px 12px; border:1px solid #e2e8f0;"></td>
              </tr>
            </tfoot>
          </table>
        </div>
      </div>
    `;
  });

  container.innerHTML = html;
}

// ─── Render Maintenance Details Tab ───
function renderMaintDetailsTab(selectedKey, yr, mo) {
  const MONTH_NAMES = ['January','February','March','April','May','June','July','August','September','October','November','December'];
  const container = document.getElementById('maintDetailsContainer');
  const label     = document.getElementById('maintDetailMonthLabel');
  if (!container) return;

  if (label) label.textContent = `${MONTH_NAMES[mo - 1]} ${yr}`;

  // Gather all maintenance entries for this month
  const monthMaintEntries = (state.maintenance || []).filter(m => {
    if (!m.date) return false;
    const d = new Date(m.date);
    return d.getFullYear() === yr && (d.getMonth() + 1) === mo;
  });

  if (monthMaintEntries.length === 0) {
    container.innerHTML = `<div style="text-align:center; padding:40px; color:var(--text-muted); font-size:0.95rem;">No maintenance entries found for this month.</div>`;
    return;
  }

  // Group maintenance entries by vehicle
  const byVehicle = {};
  monthMaintEntries.forEach(m => {
    const vObj = state.vehicles.find(v => v.id === m.vehicle || `${v.name} (${v.plate})` === m.vehicle || v.plate === m.vehicle);
    const vId  = vObj ? vObj.id : (m.vehicle || 'unknown');
    const plate = vObj ? vObj.plate : (m.vehicle || '—');
    const model = vObj ? vObj.name  : '—';
    const defaultDriver = vObj ? getDriverName(vObj.driver) : '—';
    if (!byVehicle[vId]) byVehicle[vId] = { plate, model, defaultDriver, entries: [] };
    byVehicle[vId].entries.push(m);
  });

  // Sort each vehicle's entries by date ascending
  Object.values(byVehicle).forEach(vData => {
    vData.entries.sort((a, b) => new Date(a.date) - new Date(b.date));
  });

  // Sort vehicles by plate
  const sortedVehicles = Object.values(byVehicle).sort((a, b) => a.plate.localeCompare(b.plate));

  let html = '';
  sortedVehicles.forEach(vData => {
    const totalCost = vData.entries.reduce((s, m) => s + (Number(m.cost) || 0), 0);
    const jobsCount = vData.entries.length;

    const rows = vData.entries.map((m, idx) => {
      const driverName = m.driver ? getDriverName(m.driver) : vData.defaultDriver;
      const statusHtml = statusBadge(m.status || 'Completed');
      return `
        <tr style="background:${idx % 2 === 0 ? '#ffffff' : '#f8fafc'};">
          <td style="padding:9px 12px; border:1px solid #e2e8f0; color:#64748b; font-size:0.85rem;">${idx + 1}</td>
          <td style="padding:9px 12px; border:1px solid #e2e8f0; font-weight:600; color:#0f172a;">${formatDate(m.date)}</td>
          <td style="padding:9px 12px; border:1px solid #e2e8f0; color:#1e3a8a; font-weight:700;">${m.type || 'General Maintenance'}</td>
          <td style="padding:9px 12px; border:1px solid #e2e8f0; color:#475569; font-weight:600;">${driverName}</td>
          <td style="padding:9px 12px; border:1px solid #e2e8f0; color:#ea580c; font-weight:700; text-align:right;">${fmtPKR(m.cost)}</td>
          <td style="padding:9px 12px; border:1px solid #e2e8f0; text-align:center;">${statusHtml}</td>
          <td style="padding:9px 12px; border:1px solid #e2e8f0; color:#475569; font-size:0.85rem; max-width:260px;">${m.notes || '—'}</td>
        </tr>
      `;
    }).join('');

    html += `
      <div class="maint-detail-vehicle-block" data-search="${vData.plate.toLowerCase()} ${vData.model.toLowerCase()} ${vData.defaultDriver.toLowerCase()} ${vData.entries.map(e => (e.type||'') + ' ' + (e.notes||'')).join(' ').toLowerCase()}" style="margin-bottom:28px;">
        <div style="display:flex; align-items:center; gap:12px; margin-bottom:10px; flex-wrap:wrap;">
          <span style="background:#1e3a8a; color:#fff; font-weight:800; font-size:0.85rem; padding:4px 14px; border-radius:20px;">🚗 ${vData.plate}</span>
          <span style="color:#64748b; font-size:0.85rem; font-weight:600;">${vData.model}</span>
          <span style="margin-left:auto; background:#ffedd5; color:#c2410c; font-weight:800; font-size:0.85rem; padding:4px 14px; border-radius:20px;">Total: ${fmtPKR(totalCost)} · ${jobsCount} record${jobsCount > 1 ? 's' : ''}</span>
        </div>
        <div style="overflow-x:auto; border-radius:10px; border:1px solid #e2e8f0; box-shadow:0 1px 4px rgba(0,0,0,0.05);">
          <table style="width:100%; border-collapse:collapse; font-size:0.88rem;">
            <thead>
              <tr style="background:#f1f5f9;">
                <th style="padding:9px 12px; text-align:left; border:1px solid #e2e8f0; color:#64748b; font-size:0.8rem; font-weight:700;">#</th>
                <th style="padding:9px 12px; text-align:left; border:1px solid #e2e8f0; color:#1e3a8a; font-weight:700;">DATE</th>
                <th style="padding:9px 12px; text-align:left; border:1px solid #e2e8f0; color:#1e3a8a; font-weight:700;">MAINTENANCE TYPE</th>
                <th style="padding:9px 12px; text-align:left; border:1px solid #e2e8f0; color:#64748b; font-weight:700;">DRIVER</th>
                <th style="padding:9px 12px; text-align:right; border:1px solid #e2e8f0; color:#ea580c; font-weight:700;">AMOUNT (PKR)</th>
                <th style="padding:9px 12px; text-align:center; border:1px solid #e2e8f0; color:#64748b; font-weight:700;">STATUS</th>
                <th style="padding:9px 12px; text-align:left; border:1px solid #e2e8f0; color:#64748b; font-weight:700;">WORK DETAILS / NOTES</th>
              </tr>
            </thead>
            <tbody>
              ${rows}
            </tbody>
            <tfoot>
              <tr style="background:#fff7ed; font-weight:800; border-top:2px solid #0f172a;">
                <td colspan="4" style="padding:10px 12px; border:1px solid #e2e8f0; text-align:right; color:#0f172a; font-size:0.9rem;">TOTAL MAINTENANCE</td>
                <td style="padding:10px 12px; border:1px solid #e2e8f0; text-align:right; color:#c2410c; font-size:1rem;">${fmtPKR(totalCost)}</td>
                <td colspan="2" style="padding:10px 12px; border:1px solid #e2e8f0;"></td>
              </tr>
            </tfoot>
          </table>
        </div>
      </div>
    `;
  });

  container.innerHTML = html;
}

// ─── Filter Fuel Details by Vehicle Search ───
function filterFuelDetails() {
  const search = (document.getElementById('fuelDetailSearch')?.value || '').toLowerCase().trim();
  const blocks = document.querySelectorAll('.fuel-detail-vehicle-block');
  let visibleCount = 0;

  blocks.forEach(block => {
    const plateModel = block.getAttribute('data-plate') || '';
    const match = !search || plateModel.includes(search);
    block.style.display = match ? 'block' : 'none';
    if (match) visibleCount++;
  });

  // Show "no results" message if nothing matches
  let noResultEl = document.getElementById('fuelDetailNoResult');
  if (!noResultEl) {
    noResultEl = document.createElement('div');
    noResultEl.id = 'fuelDetailNoResult';
    noResultEl.style.cssText = 'text-align:center; padding:30px; color:var(--text-muted); font-size:0.95rem; font-weight:600;';
    noResultEl.textContent = '❌ Koi vehicle nahi mila. Dobara search karein.';
    document.getElementById('fuelDetailsContainer')?.after(noResultEl);
  }
  noResultEl.style.display = (visibleCount === 0 && search) ? 'block' : 'none';
}

// ─── Filter Maintenance Details by Vehicle Search ───
function filterMaintDetails() {
  const search = (document.getElementById('maintDetailSearch')?.value || '').toLowerCase().trim();
  const blocks = document.querySelectorAll('.maint-detail-vehicle-block');
  let visibleCount = 0;

  blocks.forEach(block => {
    const searchData = block.getAttribute('data-search') || '';
    const match = !search || searchData.includes(search);
    block.style.display = match ? 'block' : 'none';
    if (match) visibleCount++;
  });

  // Show "no results" message if nothing matches
  let noResultEl = document.getElementById('maintDetailNoResult');
  if (!noResultEl) {
    noResultEl = document.createElement('div');
    noResultEl.id = 'maintDetailNoResult';
    noResultEl.style.cssText = 'text-align:center; padding:30px; color:var(--text-muted); font-size:0.95rem; font-weight:600;';
    noResultEl.textContent = '❌ Koi maintenance record nahi mila. Dobara search karein.';
    document.getElementById('maintDetailsContainer')?.after(noResultEl);
  }
  noResultEl.style.display = (visibleCount === 0 && search) ? 'block' : 'none';
}

// ─── Helpers ───
function getDriverName(id) {
  if (!id || id === '-' || id === '—' || id === 'null' || id === 'undefined') return '—';
  const d = (state.drivers || []).find(x => x.id === id || x.name === id || (x.name && x.name.toLowerCase().trim() === String(id).toLowerCase().trim()));
  if (d && d.name) return d.name;
  if (/^[a-z0-9_]{10,}$/i.test(String(id).trim())) return '—';
  return String(id).trim() || '—';
}
function getVehicleName(id) {
  const v = state.vehicles.find(x => x.id === id);
  return v ? (v.plate ? `${v.name} (${v.plate})` : v.name) : (id || '—');
}
function statusBadge(s) {
  const map = {
    'Active':'green','Idle':'blue','Maintenance':'orange',
    'Completed':'green','Pending':'orange','In Progress':'blue'
  };
  return `<span class="badge badge-${map[s]||'purple'}">${s}</span>`;
}
function formatDate(d) { return d ? new Date(d).toLocaleDateString('en-PK') : '—'; }

function generateNextBillNo() {
  if (!state.bills) state.bills = [];
  let maxNum = 0;
  state.bills.forEach(b => {
    if (b.billNo && String(b.billNo).startsWith('VFP-A-')) {
      const num = parseInt(String(b.billNo).replace('VFP-A-', ''), 10);
      if (!isNaN(num) && num > maxNum) {
        maxNum = num;
      }
    }
  });
  const nextNum = maxNum + 1;
  return `VFP-A-${String(nextNum).padStart(2, '0')}`;
}

function resequenceAllBills() {
  if (!state.bills || !state.bills.length) return;
  
  // Sort bills chronologically by date ascending
  state.bills.sort((a, b) => new Date(a.date) - new Date(b.date));
  
  let needsSave = false;
  state.bills.forEach((b, i) => {
    const seq = String(i + 1).padStart(2, '0');
    const newBillNo = `VFP-A-${seq}`;
    if (b.billNo !== newBillNo) {
      b.billNo = newBillNo;
      needsSave = true;
    }
  });
  
  if (needsSave) {
    saveState();
  }
}

function renderTokenTax() {
  const search = (document.getElementById('tokentaxSearch')?.value || '').toLowerCase();
  const tbody = document.getElementById('tokentaxBody');
  if (!tbody) return;

  const filtered = state.vehicles.filter(v => {
    // Show vehicles > 1000 CC (parse from power field e.g. "1300 CC" or "1800")
    const ccVal = parseInt((v.power || '').toString().replace(/[^0-9]/g, '')) || 0;
    const isOver1000cc = ccVal > 1000;
    const matchesSearch = !search || v.plate.toLowerCase().includes(search) || v.name.toLowerCase().includes(search);
    return isOver1000cc && matchesSearch;
  });

  tbody.innerHTML = filtered.length ? filtered.map((v, i) => {
    const deptAllot = state.allotments.find(a => a.vehicle === v.id && a.status === 'Active');
    const vDept = v.dept || (deptAllot ? deptAllot.department : '');
    const deptLabel = {
      general: 'General', scm: 'SCM', accounts: 'Accounts',
      sale: 'Sale', admin: 'Admin', production: 'Production'
    }[vDept] || vDept || 'General';

    const ccVal = parseInt((v.power || '').toString().replace(/[^0-9]/g, '')) || 0;
    return `
      <tr>
        <td>${i + 1}</td>
        <td><code style="background:var(--bg3);padding:2px 6px;border-radius:4px;font-size:0.8rem;">${v.plate || '-'}</code></td>
        <td><strong>${v.name || '-'}</strong></td>
        <td>${v.type || '-'}</td>
        <td><strong>${v.designation || '-'}</strong></td>
        <td><span class="status-badge ${v.tokenStatus === 'Paid' ? 'active' : 'inactive'}" style="padding:2px 8px;border-radius:4px;font-size:0.75rem;font-weight:600;">${v.tokenStatus || 'Unpaid'}</span></td>
        <td>${v.tokenStartDate || '-'}</td>
        <td>${v.tokenExpiryDate || '-'}</td>
        <td style="text-align:center;">
          <button class="btn-icon-sm" onclick="editTokenTax('${v.id}')" title="Edit Token & Tax">✏️</button>
          <button class="btn-icon-sm" onclick="deleteTokenTax('${v.id}')" title="Delete" style="color:#ef4444;">🗑️</button>
        </td>
      </tr>
    `;
  }).join('') : `<tr><td colspan="9" style="text-align:center;padding:20px;color:var(--text-muted);">No Token Tax records found</td></tr>`;
}
function fmtPKR(n) { return 'PKR ' + Number(n).toLocaleString('en-PK'); }

// ─── DASHBOARD ───
function renderDashboard() {
  document.getElementById('stat-total').textContent = state.vehicles.length;
  
  const bikeCount = state.vehicles.filter(v => v.type === 'Motorcycle').length;
  if (document.getElementById('stat-bikes')) document.getElementById('stat-bikes').textContent = bikeCount;
  
  const currentMonth = new Date().toISOString().slice(0, 7); // YYYY-MM
  const monthlyFuelCost = state.fuel.reduce((sum, f) => {
    if (f && f.date && typeof f.date === 'string' && f.date.startsWith(currentMonth)) {
      return sum + (Number(f.cost) || 0);
    }
    return sum;
  }, 0);
  if (document.getElementById('stat-fuel-cost')) document.getElementById('stat-fuel-cost').textContent = fmtPKR(monthlyFuelCost);
  
  const pendingMaintenance = state.maintenance.filter(m => m.status === 'Pending').length;
  const maintenanceCount = pendingMaintenance > 0 ? pendingMaintenance : state.vehicles.filter(v => v.status === 'Maintenance').length;
  if (document.getElementById('stat-maintenance')) document.getElementById('stat-maintenance').textContent = maintenanceCount;

  // Recent vehicles table
  const tbody = document.getElementById('dashRecentBody');
  const recent = [...state.vehicles].slice(-5).reverse();
  tbody.innerHTML = recent.length ? recent.map(v => `
    <tr>
      <td><strong>${v.name}</strong></td>
      <td><code style="background:var(--bg3);padding:2px 8px;border-radius:6px;font-size:0.82rem;">${v.plate}</code></td>
      <td>${getDriverName(v.driver)}</td>
      <td>${statusBadge(v.status)}</td>
      <td>${getMostRecentService(v.id)}</td>
    </tr>
  `).join('') : `<tr><td colspan="5"><div class="empty-state"><div class="empty-icon">🚗</div><p>No vehicles yet</p></div></td></tr>`;

  drawStatusChart();
  drawFuelChart();
}

function getMostRecentService(vid) {
  const recs = state.maintenance.filter(m => m.vehicle === vid).sort((a,b) => new Date(b.date)-new Date(a.date));
  return recs.length ? formatDate(recs[0].date) : '—';
}

// ─── VEHICLES ───
function renderVehicles() {
  const statusF = document.getElementById('vehicleStatusFilter').value;
  const typeF   = document.getElementById('vehicleTypeFilter').value;
  const deptF   = document.getElementById('vehicleDeptFilter').value;
  const search  = document.getElementById('vehicleSearch').value.toLowerCase();
  
  let list = state.vehicles.filter(v => {
    const deptAllot = state.allotments.find(a => a.vehicle === v.id && a.status === 'Active');
    const vDept = v.dept || (deptAllot ? deptAllot.department : '');
    return (!statusF || v.status === statusF) &&
           (!typeF   || v.type   === typeF) &&
           (!deptF   || vDept    === deptF) &&
           (!search  || v.name.toLowerCase().includes(search) ||
                        v.plate.toLowerCase().includes(search) ||
                        (v.chassis||'').toLowerCase().includes(search) ||
                        (v.designation||'').toLowerCase().includes(search));
  });
  
  const tbody = document.getElementById('vehiclesBody');
  
  const deptPill = (dept) => {
    if (!dept) return '<span style="color:var(--text-muted)">-</span>';
    const map = { general: ['General','🏢','dept-general'], sale: ['Sale','💼','dept-sale'], admin: ['Admin','🛡️','dept-admin'] };
    const [label, icon, cls] = map[dept] || [dept, '', ''];
    return `<span class="dept-pill ${cls}">${icon} ${label}</span>`;
  };
  
  const insBadge = (ins) => {
    if (ins === 'insured') return '<span class="ins-badge ins-insured">✓ Insured</span>';
    if (ins === 'expired') return '<span class="ins-badge ins-expired">⚠ Expired</span>';
    return '<span class="ins-badge ins-not">— Not Insured</span>';
  };
  
  tbody.innerHTML = list.length ? list.map((v, i) => {
    const driverName = getDriverName(v.driver);
    const deptAllot  = state.allotments.find(a => a.vehicle === v.id && a.status === 'Active');
    const dept       = v.dept || (deptAllot ? deptAllot.department : '');
    const etagIcon   = v.etag    ? '<span title="E-Tag/Token" style="color:var(--green)">✔</span>' : '<span style="color:var(--red)">✖</span>';
    const envIcon    = v.envTag  ? '<span title="Env Tag"    style="color:var(--green)">✔</span>' : '<span style="color:var(--red)">✖</span>';
    return `
      <tr ondblclick="openEditVehicle('${v.id}')" style="cursor:pointer;" title="Double click to edit">
        <td>${i+1}</td>
        <td><code style="background:var(--bg3);padding:2px 8px;border-radius:6px;font-size:0.82rem;">${v.plate}</code></td>
        <td>
          <div style="display:flex;align-items:center;gap:8px;">
            <div style="width:28px;height:28px;border-radius:6px;background:linear-gradient(135deg,var(--accent),#8b5cf6);display:flex;align-items:center;justify-content:center;font-size:1rem;flex-shrink:0;">${typeEmoji(v.type)}</div>
            <div>
              <div style="font-weight:600;font-size:0.88rem;">${v.name}</div>
              <div style="font-size:0.72rem;color:var(--text-muted);">${v.year || ''}</div>
            </div>
          </div>
        </td>
        <td><span style="font-size:0.85rem;">${v.type}</span></td>
        <td>
          <div style="font-size:0.85rem;">${v.color || '—'}</div>
          <div style="font-size:0.72rem;color:var(--text-muted);">${v.power || ''}</div>
        </td>
        <td>
          <div style="font-size:0.78rem;font-family:monospace;color:var(--text-secondary);">${v.chassis || '—'}</div>
          <div style="font-size:0.72rem;color:var(--text-muted);margin-top:2px;">${v.engine || ''}</div>
        </td>
        <td>
          <div style="font-size:0.85rem;font-weight:600;">${driverName}</div>
          <div style="font-size:0.72rem;color:var(--text-muted);">${v.empId ? 'ID: ' + v.empId + ' | ' : ''}${v.designation || ''}</div>
          ${v.allotmentDate ? `<div style="font-size:0.68rem;color:var(--accent);margin-top:2px;">📅 Allot: ${formatDate(v.allotmentDate)}</div>` : ''}
        </td>
        <td>${deptPill(dept)}</td>
        <td>${insBadge(v.insurance)}</td>
        <td style="white-space:nowrap;">
          <span title="E-Tag/Token">${etagIcon}</span>
          <span title="Env Tag" style="margin-left:4px;">${envIcon}</span>
        </td>
        <td>
          <div style="display:flex;gap:6px;">
            <button class="btn-icon edit" onclick="openEditVehicle('${v.id}')">✏ Edit</button>
            <button class="btn-icon delete" onclick="confirmDelete('vehicle','${v.id}')">🗑</button>
          </div>
        </td>
      </tr>
    `;
  }).join('') : `<tr><td colspan="11"><div class="empty-state"><div class="empty-icon">🚗</div><p>No vehicles found</p></div></td></tr>`;
}

function typeEmoji(t) {
  return {Car:'🚗',Truck:'🚛',Van:'🚐',Motorcycle:'🏍',Bus:'🚌'}[t] || '🚙';
}

// ─── BIKES ───
function renderBikes() {
  const deptF   = document.getElementById('bikeDeptFilter').value;
  const search  = document.getElementById('bikeSearch').value.toLowerCase();
  
  let list = state.vehicles.filter(v => {
    // Only bikes (Motorcycle)
    if (v.type !== 'Motorcycle') return false;
    const deptAllot = state.allotments.find(a => a.vehicle === v.id && a.status === 'Active');
    const vDept = v.dept || (deptAllot ? deptAllot.department : '');
    return (!deptF   || vDept    === deptF) &&
           (!search  || v.name.toLowerCase().includes(search) ||
                        v.plate.toLowerCase().includes(search));
  });
  
  const tbody = document.getElementById('bikesBody');
  if (!tbody) return;
  
  const deptPill = (dept) => {
    if (!dept) return '<span style="color:var(--text-muted)">-</span>';
    const map = { general: ['General','🏢','dept-general'], sale: ['Sale','💼','dept-sale'], admin: ['Admin','🛡️','dept-admin'] };
    const [label, icon, cls] = map[dept] || [dept, '', ''];
    return `<span class="dept-pill ${cls}">${icon} ${label}</span>`;
  };
  
  tbody.innerHTML = list.length ? list.map((v, i) => {
    const dept = v.dept || '-';
    // bikeDriver is now stored as a text name string directly
    const riderName = v.driverName || v.driver || '-';
    
    return `
      <tr ondblclick="openEditBike('${v.id}')" style="cursor:pointer;" title="Double click to edit">
        <td>${i+1}</td>
        <td><code style="background:var(--bg3);padding:2px 6px;border-radius:4px;font-size:0.8rem;">${v.plate || '-'}</code></td>
        <td>
          <div style="font-weight:600;">${v.name || '-'}</div>
          <div style="font-size:0.75rem;color:var(--text-muted);">${v.year || ''}</div>
        </td>
        <td>${v.color || '-'}</td>
        <td>
          <div style="font-size:0.8rem;">${v.engine ? '⚙️ ' + v.engine : '-'}</div>
          <div style="font-size:0.75rem;color:var(--text-muted);">${v.chassis ? '🔗 ' + v.chassis : ''}</div>
        </td>
        <td>
          <div style="font-size:0.85rem;font-weight:600;">${riderName}</div>
        </td>
        <td>${deptPill(dept)}</td>
        <td>
          <button class="btn-icon edit" onclick="openEditBike('${v.id}')" title="Edit">✏️</button>
          <button class="btn-icon delete" onclick="deleteVehicle('${v.id}')" title="Delete">🗑</button>
        </td>
      </tr>
    `;
  }).join('') : `<tr><td colspan="8" style="text-align:center;padding:20px;color:var(--text-muted);">No bikes found</td></tr>`;
}

document.getElementById('addBikeBtn').addEventListener('click', () => {
  editingId.vehicle = null;
  document.getElementById('bikeModalTitle').textContent = 'Add Bike';
  document.getElementById('bikeForm').reset();
  
  // Populate riders
  const driverSel = document.getElementById('bikeDriver');
  driverSel.innerHTML = '<option value="">— Unassigned —</option>' + 
    state.drivers.map(d => `<option value="${d.id}">${d.name}</option>`).join('');
    
  openModal('bikeModal');
});

function openEditBike(id) {
  const v = state.vehicles.find(x => x.id === id);
  if (!v) return;
  editingId.vehicle = id;
  document.getElementById('bikeModalTitle').textContent = 'Edit Bike';
  
  document.getElementById('bikePlate').value   = v.plate || '';
  document.getElementById('bikeYear').value    = v.year || '';
  document.getElementById('bikeName').value    = v.name || '';
  document.getElementById('bikeColor').value   = v.color || '';
  document.getElementById('bikeDept').value    = v.dept || '';
  document.getElementById('bikeStatus').value  = v.status || 'Active';
  document.getElementById('bikeDriver').value  = v.driverName || v.driver || '';
  document.getElementById('bikeEngine').value  = v.engine || '';
  document.getElementById('bikeChassis').value = v.chassis || '';
    
  openModal('bikeModal');
}

document.getElementById('bikeForm')?.addEventListener('submit', e => {
  e.preventDefault();
  const rec = {
    id: editingId.vehicle || uid(),
    plate:      document.getElementById('bikePlate').value.trim(),
    year:       document.getElementById('bikeYear').value,
    name:       document.getElementById('bikeName').value.trim(),
    type:       'Motorcycle',
    color:      document.getElementById('bikeColor').value.trim(),
    dept:       document.getElementById('bikeDept').value,
    status:     document.getElementById('bikeStatus').value,
    driverName: document.getElementById('bikeDriver').value.trim(),
    driver:     '', // text name stored in driverName
    engine:     document.getElementById('bikeEngine').value.trim().toUpperCase(),
    chassis:    document.getElementById('bikeChassis').value.trim().toUpperCase()
  };
  
  if (editingId.vehicle) {
    state.vehicles = state.vehicles.map(v => v.id === editingId.vehicle ? {...v, ...rec} : v);
    const activeA = state.allotments.find(a => a.vehicle === editingId.vehicle && a.status === 'Active');
    if (activeA && activeA.department !== rec.dept) {
      activeA.status = 'Returned';
      activeA.returnDate = new Date().toISOString().split('T')[0];
      state.allotments.push({ id: uid(), department: rec.dept, vehicle: rec.id, date: new Date().toISOString().split('T')[0], returnDate: '', status: 'Active', notes: 'Re-assigned' });
    }
    showToast('Bike updated ✅', 'success');
  } else {
    state.vehicles.push(rec);
    if (rec.dept) {
      state.allotments.push({ id: uid(), department: rec.dept, vehicle: rec.id, date: new Date().toISOString().split('T')[0], returnDate: '', status: 'Active', notes: '' });
    }
    showToast('Bike added ✅', 'success');
  }
  saveState(); closeModal('bikeModal'); renderBikes(); updateDashStats(); renderSidebarDeptVehicles();
});

// ─── DRIVERS ───
function renderDrivers() {
  const search = document.getElementById('driverSearch').value.toLowerCase();
  let list = state.drivers.filter(d => {
    const matchesSearch = !search || d.name.toLowerCase().includes(search) || d.phone.includes(search);
    const isCompany = (d.type === 'Company' || !d.type);
    return matchesSearch && isCompany;
  });
  const grid = document.getElementById('driversGrid');
  grid.innerHTML = list.length ? list.map(d => {
    const initials = d.name.split(' ').map(w => w[0]).join('').toUpperCase().slice(0,2);
    const expiry = d.licenseExpiry ? new Date(d.licenseExpiry) : null;
    const expired = expiry && expiry < new Date();
    const dType = d.type || 'Company';
    return `
      <div class="driver-card" ondblclick="openEditDriver('${d.id}')" style="cursor:pointer;" title="Double click to edit">
        <div class="driver-avatar">${initials}</div>
        <div class="driver-name">${d.name}</div>
        <div class="driver-meta" style="margin-bottom:8px;"><span class="badge" style="background:var(--accent-dim);color:var(--accent);font-size:0.7rem;padding:2px 8px;border-radius:4px;font-weight:600;">${dType} Driver</span></div>
        <div class="driver-meta">📞 ${d.phone}</div>
        <div class="driver-detail">🪪 License: <span>${d.license}</span></div>
        <div class="driver-detail">📅 Expiry: <span style="color:${expired?'var(--red)':'var(--green)'}">${formatDate(d.licenseExpiry)}</span></div>
        <div class="driver-detail">📍 ${d.address || '—'}</div>
        <div class="driver-actions">
          <button class="btn-icon edit" onclick="openEditDriver('${d.id}')">✏ Edit</button>
          <button class="btn-icon delete" onclick="confirmDelete('driver','${d.id}')">🗑</button>
        </div>
      </div>
    `;
  }).join('') : `<div class="empty-state" style="grid-column:1/-1;"><div class="empty-icon">👤</div><p>No drivers found</p></div>`;
}

// ─── MAINTENANCE ───
function renderMaintenance() {
  if (!state.maintenance) state.maintenance = [];
  const search = (document.getElementById('maintenanceSearch')?.value || '').toLowerCase();
  const statusFilter = document.getElementById('maintenanceStatusFilter')?.value || '';
  
  // Populate Month Filter Dropdown
  const monthSel = document.getElementById('maintenanceMonthSelect');
  let selectedMonth = 'all';
  if (monthSel) {
    const prevVal = monthSel.value;
    const MONTH_NAMES = ['January','February','March','April','May','June','July','August','September','October','November','December'];
    const monthSet = new Set();
    state.maintenance.forEach(m => {
      if (m.date) {
        const d = new Date(m.date);
        if (!isNaN(d.getTime())) {
          monthSet.add(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`);
        }
      }
    });
    const allMonths = [...monthSet].sort().reverse();
    
    let optionsHtml = '<option value="all">📁 All Months (Full History)</option>';
    allMonths.forEach(m => {
      const [y, mo] = m.split('-');
      const mName = MONTH_NAMES[parseInt(mo, 10) - 1];
      const count = state.maintenance.filter(x => x.date && x.date.startsWith(m)).length;
      optionsHtml += `<option value="${m}">📅 ${mName} ${y} (${count} entries)</option>`;
    });
    monthSel.innerHTML = optionsHtml;
    
    if (prevVal === 'all' || allMonths.includes(prevVal)) {
      monthSel.value = prevVal;
      selectedMonth = prevVal;
    } else if (allMonths.length > 0 && prevVal !== 'all') {
      monthSel.value = allMonths[0]; // default to most recent month if previous value invalid
      selectedMonth = allMonths[0];
    }
  }

  const filtered = state.maintenance.filter(m => {
    const vName = getVehicleName(m.vehicle).toLowerCase();
    const mType = (m.type || '').toLowerCase();
    const mNotes = (m.notes || '').toLowerCase();
    const matchSearch = !search || vName.includes(search) || mType.includes(search) || mNotes.includes(search);
    const matchStatus = !statusFilter || m.status === statusFilter;
    const matchMonth = selectedMonth === 'all' || (m.date && m.date.startsWith(selectedMonth));
    return matchSearch && matchStatus && matchMonth;
  });

  const tbody = document.getElementById('maintenanceBody');
  tbody.innerHTML = filtered.length ? [...filtered].reverse().map((m, i) => `
    <tr ondblclick="openEditMaintenance('${m.id}')" style="cursor:pointer;" title="Double click to edit">
      <td>${i+1}</td>
      <td><strong>${getVehicleName(m.vehicle)}</strong></td>
      <td>${m.driver ? getDriverName(m.driver) : '-'}</td>
      <td>${m.type}</td>
      <td>${formatDate(m.date)}</td>
      <td>${fmtPKR(m.cost)}</td>
      <td>${statusBadge(m.status)}</td>
      <td style="max-width:180px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;" title="${m.notes}">${m.notes || '-'}</td>
      <td>
        <div style="display:flex;gap:6px;">
          <button class="btn-icon edit" onclick="openEditMaintenance('${m.id}')">✏ Edit</button>
          <button class="btn-icon delete" onclick="confirmDelete('maintenance','${m.id}')">🗑</button>
        </div>
      </td>
    </tr>
  `).join('') : `<tr><td colspan="9"><div class="empty-state"><div class="empty-icon">🔧</div><p>No maintenance records found</p></div></td></tr>`;
}

// ─── FUEL ───
function renderFuel() {
  if (!state.fuel) state.fuel = [];
  const MONTH_NAMES = ['January','February','March','April','May','June','July','August','September','October','November','December'];
  const now = new Date();
  const curMonthKey = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`;
  const curMonthName = MONTH_NAMES[now.getMonth()];
  const curYear = now.getFullYear();

  // Populate Month Filter Dropdown
  const monthSel = document.getElementById('fuelMonthSelect');
  let selectedMonth = curMonthKey;
  if (monthSel) {
    const monthSet = new Set();
    monthSet.add(curMonthKey);
    state.fuel.forEach(f => {
      if (f.date) {
        const d = new Date(f.date);
        if (!isNaN(d.getTime())) {
          monthSet.add(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`);
        }
      }
    });
    const allMonths = [...monthSet].sort().reverse();
    const prevVal = monthSel.value;

    let optionsHtml = '';
    optionsHtml += `<option value="${curMonthKey}">📅 Current Month (${curMonthName} ${curYear})</option>`;
    optionsHtml += `<option value="all">📂 All Months (Full History)</option>`;

    allMonths.forEach(m => {
      if (m !== curMonthKey) {
        const [y, mo] = m.split('-');
        const mName = MONTH_NAMES[parseInt(mo, 10) - 1];
        const count = state.fuel.filter(f => f.date && f.date.startsWith(m)).length;
        optionsHtml += `<option value="${m}">📁 ${mName} ${y} (${count} entries)</option>`;
      }
    });

    monthSel.innerHTML = optionsHtml;
    if (prevVal && (prevVal === 'all' || allMonths.includes(prevVal))) {
      monthSel.value = prevVal;
      selectedMonth = prevVal;
    } else {
      monthSel.value = curMonthKey;
      selectedMonth = curMonthKey;
    }
  }

  // Populate Vehicle Filter Dropdown
  const vehSel = document.getElementById('fuelVehicleFilter');
  if (vehSel && vehSel.options.length <= 1) {
    const prevVeh = vehSel.value;
    vehSel.innerHTML = '<option value="">All Vehicles</option>' +
      (state.vehicles || []).map(v => `<option value="${v.id}">${v.name} (${v.plate})</option>`).join('');
    if (prevVeh) vehSel.value = prevVeh;
  }

  const selectedVeh = vehSel ? vehSel.value : '';
  const search = (document.getElementById('fuelSearch')?.value || '').toLowerCase().trim();

  // Calculate All-Time total fuel cost
  const allTimeCost = state.fuel.reduce((s, f) => s + (Number(f.cost) || 0), 0);

  // Filter fuel entries
  let filteredFuel = [...state.fuel];
  if (selectedMonth && selectedMonth !== 'all') {
    filteredFuel = filteredFuel.filter(f => f.date && f.date.startsWith(selectedMonth));
  }
  if (selectedVeh) {
    filteredFuel = filteredFuel.filter(f => {
      const vObj = state.vehicles.find(v => v.id === selectedVeh);
      return f.vehicle === selectedVeh || (vObj && (f.vehicle === vObj.plate || f.vehicle === `${vObj.name} (${vObj.plate})`));
    });
  }
  if (search) {
    filteredFuel = filteredFuel.filter(f => {
      const vObj = state.vehicles.find(v => v.id === f.vehicle || v.plate === f.vehicle || `${v.name} (${v.plate})` === f.vehicle);
      const plate = vObj ? vObj.plate : (f.vehicle || '');
      const name = vObj ? vObj.name : '';
      const pump = f.pumpName || '';
      const batch = f.batchId || '';
      return plate.toLowerCase().includes(search) ||
             name.toLowerCase().includes(search) ||
             pump.toLowerCase().includes(search) ||
             batch.toLowerCase().includes(search) ||
             (f.date || '').includes(search);
    });
  }

  // Group filtered fuel entries by batchId
  const batches = {};
  filteredFuel.forEach(f => {
    const bid = f.batchId || f.id;
    if (!batches[bid]) batches[bid] = { batchId: bid, date: f.date, count: 0, litres: 0, cost: 0, entries: [] };
    batches[bid].count++;
    batches[bid].litres += Number(f.litres) || 0;
    batches[bid].cost += Number(f.cost) || 0;
    batches[bid].entries.push(f);
  });
  
  const batchList = Object.values(batches).sort((a,b) => new Date(b.date) - new Date(a.date));

  // Calculate period totals
  const periodLitres = filteredFuel.reduce((s, f) => s + (Number(f.litres) || 0), 0);
  const periodCost   = filteredFuel.reduce((s, f) => s + (Number(f.cost) || 0), 0);
  const periodAvg    = batchList.length ? (periodLitres / batchList.length).toFixed(2) + ' L/voucher' : '0.00 L/voucher';

  const isCurrentMonth = selectedMonth === curMonthKey;
  const isAll = selectedMonth === 'all';
  let periodName = 'This Month';
  if (isAll) periodName = 'All Time';
  else if (!isCurrentMonth) {
    const [y, mo] = selectedMonth.split('-');
    periodName = `${MONTH_NAMES[parseInt(mo, 10) - 1]} ${y}`;
  }

  // Update card labels
  const labelLitres = document.getElementById('fuel-label-litres');
  if (labelLitres) labelLitres.textContent = `${periodName} Fuel (Litres)`;
  const labelCost = document.getElementById('fuel-label-cost');
  if (labelCost) labelCost.textContent = `${periodName} Fuel Cost`;
  const labelAvg = document.getElementById('fuel-label-avg');
  if (labelAvg) labelAvg.textContent = `${periodName} Avg per Voucher`;

  // Update card values
  if (document.getElementById('fuel-total-litres')) document.getElementById('fuel-total-litres').textContent = periodLitres.toFixed(2) + ' L';
  if (document.getElementById('fuel-total-cost'))   document.getElementById('fuel-total-cost').textContent   = fmtPKR(periodCost);
  if (document.getElementById('fuel-avg'))          document.getElementById('fuel-avg').textContent          = periodAvg;
  if (document.getElementById('fuel-alltime-cost')) document.getElementById('fuel-alltime-cost').textContent = fmtPKR(allTimeCost);

  // Render Table
  const tbody = document.getElementById('fuelBody');
  if (!tbody) return;

  if (batchList.length > 0) {
    tbody.innerHTML = batchList.map((b, i) => {
      const primaryVehicle = b.entries[0] ? getVehicleName(b.entries[0].vehicle) : 'Unknown';
      const vehDisplay = b.count > 1 ? `${primaryVehicle} + ${b.count - 1} more` : primaryVehicle;
      const rate = b.litres > 0 ? (b.cost / b.litres).toFixed(2) : '—';
      const avg = b.entries[0] && b.entries[0].fuelAverage ? b.entries[0].fuelAverage : '—';
      
      return `
      <tr ondblclick="openEditFuelBatch('${b.batchId}')" style="cursor:pointer;" title="Double click to edit">
        <td style="text-align:center; font-weight:700; color:#64748b;">${i+1}</td>
        <td><strong style="color:#1e3a8a;">${vehDisplay}</strong></td>
        <td style="font-weight:600; color:#1e293b;">${formatDate(b.date)}</td>
        <td style="font-weight:700; color:#4f46e5;">${b.litres.toFixed(2)} L</td>
        <td style="color:#64748b; font-size:0.88rem;">${rate !== '—' ? 'PKR ' + rate : '—'}</td>
        <td style="font-weight:800; color:#15803d; font-size:0.95rem;">${fmtPKR(b.cost)}</td>
        <td><span style="background:#dcfce7; color:#15803d; padding:2px 8px; border-radius:10px; font-weight:700; font-size:0.78rem;">${avg}</span></td>
        <td><code style="background:var(--bg3); padding:2px 6px; border-radius:4px; font-size:0.8rem; font-weight:600;">FUEL-${b.batchId.slice(-6)}</code></td>
        <td>
          <div style="display:flex; gap:6px;">
            <button class="btn-icon edit" onclick="openEditFuelBatch('${b.batchId}')" title="Edit Voucher">✏ Edit</button>
            <button class="btn-icon delete" onclick="confirmDelete('fuelBatch','${b.batchId}')" title="Delete Voucher">🗑</button>
          </div>
        </td>
      </tr>
    `;
    }).join('');
  } else {
    const emptyMsg = isCurrentMonth
      ? `No fuel vouchers recorded for ${curMonthName} ${curYear} yet.`
      : `No fuel vouchers found for ${periodName}.`;

    tbody.innerHTML = `
      <tr>
        <td colspan="9" style="text-align:center; padding:35px 20px; color:#64748b;">
          <div style="font-size:1.05rem; font-weight:700; color:#334155; margin-bottom:8px;">${emptyMsg}</div>
          <div style="font-size:0.9rem; color:#64748b;">
            💡 Pichlay mahinay ka fuel record dekhne ke liye uper dropdown se <a href="javascript:void(0)" onclick="document.getElementById('fuelMonthSelect').value='all';renderFuel();" style="color:#2563eb; font-weight:700; text-decoration:underline;">All Months</a> ya August select karein.
          </div>
        </td>
      </tr>
    `;
  }
}

// ─── REPORTS ───
function renderReports() {
  document.getElementById('rep-vehicles').textContent = state.vehicles.length;
  document.getElementById('rep-drivers').textContent  = state.drivers.length;
  const maintCost = state.maintenance.reduce((s,m) => s + Number(m.cost), 0);
  const fuelCost  = state.fuel.reduce((s,f) => s + Number(f.cost), 0);
  document.getElementById('rep-maint-cost').textContent = fmtPKR(maintCost);
  document.getElementById('rep-fuel-cost').textContent  = fmtPKR(fuelCost);
  
  // Populate year filter
  const yearSel = document.getElementById('reportYearFilter');
  if (yearSel) {
    const years = new Set();
    state.fuel.forEach(f => f.date && years.add(f.date.substring(0, 4)));
    state.maintenance.forEach(m => m.date && years.add(m.date.substring(0, 4)));
    const sortedYears = [...years].sort().reverse();
    const currentYear = yearSel.value;
    yearSel.innerHTML = '<option value="">All Years</option>' +
      sortedYears.map(y => `<option value="${y}" ${y === currentYear ? 'selected' : ''}>${y}</option>`).join('');
  }
  
  renderMonthlyReportTable();
  drawMaintChart();
  drawTypeChart();
}

function renderMonthlyReportTable() {
  const MONTH_NAMES = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  const yearFilter = document.getElementById('reportYearFilter')?.value || '';
  
  // Build monthly data map
  const monthMap = {};
  
  const addToMonth = (dateStr, fuelLitres, fuelCost, maintCost) => {
    if (!dateStr) return;
    const d = new Date(dateStr);
    const y = d.getFullYear();
    if (yearFilter && String(y) !== yearFilter) return;
    const key = `${y}-${String(d.getMonth()+1).padStart(2,'0')}`;
    if (!monthMap[key]) monthMap[key] = { year: y, month: d.getMonth(), fuelLitres: 0, fuelCost: 0, maintCost: 0 };
    monthMap[key].fuelLitres += fuelLitres;
    monthMap[key].fuelCost   += fuelCost;
    monthMap[key].maintCost  += maintCost;
  };
  
  // Deduplicate fuel by batchId (count once per batch entry)
  const seenBatch = new Set();
  state.fuel.forEach(f => {
    addToMonth(f.date, Number(f.litres), Number(f.cost), 0);
  });
  state.maintenance.forEach(m => {
    addToMonth(m.date, 0, 0, Number(m.cost));
  });
  
  const rows = Object.entries(monthMap).sort((a, b) => b[0].localeCompare(a[0]));
  
  let totalFuelL = 0, totalFuelC = 0, totalMaintC = 0;
  
  const tbody = document.getElementById('monthlyReportBody');
  const tfoot = document.getElementById('monthlyReportFoot');
  if (!tbody) return;
  
  if (rows.length === 0) {
    tbody.innerHTML = `<tr><td colspan="5" style="text-align:center;padding:20px;color:var(--text-muted);">No data available yet</td></tr>`;
    if (tfoot) tfoot.innerHTML = '';
    return;
  }
  
  tbody.innerHTML = rows.map(([key, d]) => {
    totalFuelL  += d.fuelLitres;
    totalFuelC  += d.fuelCost;
    totalMaintC += d.maintCost;
    const total = d.fuelCost + d.maintCost;
    return `
      <tr>
        <td><strong>${MONTH_NAMES[d.month]} ${d.year}</strong></td>
        <td>${d.fuelLitres > 0 ? d.fuelLitres.toFixed(2) + ' L' : '—'}</td>
        <td>${d.fuelCost > 0 ? fmtPKR(d.fuelCost) : '—'}</td>
        <td>${d.maintCost > 0 ? fmtPKR(d.maintCost) : '—'}</td>
        <td style="font-weight:700;color:var(--accent);">${fmtPKR(total)}</td>
      </tr>
    `;
  }).join('');
  
  if (tfoot) {
    tfoot.innerHTML = `
      <tr style="background:var(--bg2);border-top:2px solid var(--border);">
        <td style="padding:12px 8px;font-weight:800;">TOTAL</td>
        <td style="padding:12px 8px;font-weight:700;">${totalFuelL.toFixed(2)} L</td>
        <td style="padding:12px 8px;font-weight:700;">${fmtPKR(totalFuelC)}</td>
        <td style="padding:12px 8px;font-weight:700;">${fmtPKR(totalMaintC)}</td>
        <td style="padding:12px 8px;font-weight:800;color:var(--accent);">${fmtPKR(totalFuelC + totalMaintC)}</td>
      </tr>
    `;
  }
}

