// ─── PDF DOWNLOAD & HISTORY ───
function downloadInvoicePDF() {
  if (typeof html2pdf === 'undefined') {
    showToast('PDF library not loaded (offline?). Printing instead...', 'warning');
    printInvoiceSheet();
    return;
  }

  // Determine which sheet is visible
  const standardSheet = document.getElementById('invoiceSheet');
  const fuelSheet = document.getElementById('fuelInvoiceSheet');
  const element = (fuelSheet && fuelSheet.style.display !== 'none') ? fuelSheet : standardSheet;
  if (!element) { showToast('No invoice to download', 'error'); return; }

  // Get bill info for history
  const billNo   = document.getElementById('invBillNoField')?.textContent || document.getElementById('invBillNoFuelField')?.textContent || '-';
  const billType = document.getElementById('invBillTypeField')?.textContent || 'Fuel';
  const vehName  = document.getElementById('invVehPlateField')?.textContent || '-';
  const amount   = document.getElementById('invTotalField')?.textContent || document.getElementById('fuelInvoiceGrandTotalSimple')?.textContent || 'PKR 0';
  
  const filename = `Invoice-${billNo}-${new Date().toISOString().split('T')[0]}.pdf`;
  
  const opt = {
    margin:       [0, 0, 0, 0],
    filename:     filename,
    image:        { type: 'jpeg', quality: 0.98 },
    html2canvas:  { scale: 2, useCORS: true, logging: false },
    jsPDF:        { unit: 'mm', format: 'a4', orientation: 'portrait' }
  };
  
  showToast('Preparing PDF...', 'info');
  
  html2pdf().set(opt).from(element).save().then(() => {
    // Record download in history
    if (!state.downloadHistory) state.downloadHistory = [];
    state.downloadHistory.unshift({
      id: uid(),
      billNo,
      type: billType,
      vehicle: vehName,
      amount,
      downloadedAt: new Date().toISOString()
    });
    saveState();
    renderDownloadHistory();
    showToast('PDF downloaded successfully! ✅', 'success');
  }).catch((e) => {
    console.error('PDF Generation Error:', e);
    showToast('PDF error: ' + (e.message || 'Check console'), 'error');
  });
}

function renderDownloadHistory() {
  const tbody = document.getElementById('downloadHistoryBody');
  if (!tbody) return;
  if (!state.downloadHistory || state.downloadHistory.length === 0) {
    tbody.innerHTML = `<tr><td colspan="6"><div class="empty-state"><div class="empty-icon">📭</div><p>No downloads yet</p></div></td></tr>`;
    return;
  }
  tbody.innerHTML = state.downloadHistory.map((h, i) => `
    <tr>
      <td>${i+1}</td>
      <td><code style="background:var(--bg3);padding:2px 6px;border-radius:4px;font-size:0.8rem;">${h.billNo}</code></td>
      <td>${h.type || '-'}</td>
      <td>${h.vehicle || '-'}</td>
      <td style="font-weight:700;color:var(--accent);">${h.amount}</td>
      <td style="font-size:0.82rem;color:var(--text-muted);">${h.downloadedAt ? new Date(h.downloadedAt).toLocaleString() : '-'}</td>
    </tr>
  `).join('');
}

function clearDownloadHistory() {
  if (!confirm('Clear all download history?')) return;
  state.downloadHistory = [];
  saveState();
  renderDownloadHistory();
  showToast('Download history cleared', 'success');
}

// ─── CANVAS CHARTS ───

function drawStatusChart() {
  const canvas = document.getElementById('statusChart');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const W = canvas.width, H = canvas.height;
  ctx.clearRect(0, 0, W, H);

  const counts = {
    Active:      state.vehicles.filter(v => v.status === 'Active').length,
    Maintenance: state.vehicles.filter(v => v.status === 'Maintenance').length,
    Idle:        state.vehicles.filter(v => v.status === 'Idle').length,
  };
  const labels = Object.keys(counts);
  const values = Object.values(counts);
  const total  = values.reduce((a,b) => a+b, 0) || 1;
  const colors = ['#22c55e', '#f97316', '#3b82f6'];

  const cx = W / 2 - 20, cy = H / 2 + 10, r = Math.min(cx, cy) - 20;
  let startAngle = -Math.PI / 2;

  values.forEach((v, i) => {
    const slice = (v / total) * 2 * Math.PI;
    ctx.beginPath();
    ctx.moveTo(cx, cy);
    ctx.arc(cx, cy, r, startAngle, startAngle + slice);
    ctx.closePath();
    ctx.fillStyle = colors[i];
    ctx.fill();
    ctx.strokeStyle = '#1e2340';
    ctx.lineWidth = 3;
    ctx.stroke();
    startAngle += slice;
  });

  // Centre hole
  ctx.beginPath();
  ctx.arc(cx, cy, r * 0.5, 0, 2 * Math.PI);
  ctx.fillStyle = '#1e2340';
  ctx.fill();

  // Legend
  let ly = 30;
  labels.forEach((l, i) => {
    ctx.fillStyle = colors[i];
    ctx.fillRect(W - 90, ly - 10, 12, 12);
    ctx.fillStyle = '#8892b0';
    ctx.font = '12px Outfit, sans-serif';
    ctx.fillText(`${l}: ${values[i]}`, W - 74, ly);
    ly += 22;
  });

  // Total
  ctx.fillStyle = '#e8eaf6';
  ctx.font = 'bold 20px Outfit, sans-serif';
  ctx.textAlign = 'center';
  ctx.fillText(total, cx, cy + 8);
  ctx.font = '11px Outfit, sans-serif';
  ctx.fillStyle = '#8892b0';
  ctx.fillText('Total', cx, cy + 22);
  ctx.textAlign = 'left';
}

function drawFuelChart() {
  const canvas = document.getElementById('fuelChart');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const W = canvas.width, H = canvas.height;
  ctx.clearRect(0, 0, W, H);

  const months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  const now = new Date();
  const last6 = [];
  for (let i = 5; i >= 0; i--) {
    const m = new Date(now.getFullYear(), now.getMonth() - i, 1);
    last6.push({ label: months[m.getMonth()], month: m.getMonth(), year: m.getFullYear() });
  }
  const values = last6.map(({month, year}) =>
    state.fuel.filter(f => {
      const d = new Date(f.date);
      return d.getMonth() === month && d.getFullYear() === year;
    }).reduce((s,f) => s + Number(f.litres), 0)
  );

  const maxV = Math.max(...values, 1);
  const padL = 50, padB = 40, padT = 20, padR = 20;
  const cW = W - padL - padR, cH = H - padB - padT;

  // Grid lines
  ctx.strokeStyle = '#2e3560';
  ctx.lineWidth = 1;
  for (let i = 0; i <= 4; i++) {
    const y = padT + (cH / 4) * i;
    ctx.beginPath(); ctx.moveTo(padL, y); ctx.lineTo(W - padR, y); ctx.stroke();
    ctx.fillStyle = '#4a5270';
    ctx.font = '11px Outfit, sans-serif';
    ctx.textAlign = 'right';
    ctx.fillText(Math.round(maxV * (1 - i/4)), padL - 8, y + 4);
  }

  // Bars
  const barW = (cW / last6.length) * 0.5;
  const grad = ctx.createLinearGradient(0, padT, 0, padT + cH);
  grad.addColorStop(0, '#6c63ff');
  grad.addColorStop(1, '#a78bfa44');

  last6.forEach(({label}, i) => {
    const x = padL + (cW / last6.length) * i + (cW / last6.length) * 0.25;
    const bH = (values[i] / maxV) * cH;
    const y  = padT + cH - bH;
    ctx.fillStyle = grad;
    ctx.beginPath();
    ctx.roundRect(x, y, barW, bH, 5);
    ctx.fill();

    // Label
    ctx.fillStyle = '#8892b0';
    ctx.font = '11px Outfit, sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText(label, x + barW / 2, H - 8);

    // Value
    if (values[i] > 0) {
      ctx.fillStyle = '#e8eaf6';
      ctx.font = 'bold 11px Outfit, sans-serif';
      ctx.fillText(values[i] + 'L', x + barW / 2, y - 5);
    }
  });
  ctx.textAlign = 'left';
}

function drawMaintChart() {
  const canvas = document.getElementById('maintChart');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const W = canvas.width, H = canvas.height;
  ctx.clearRect(0, 0, W, H);

  const data = state.vehicles.map(v => ({
    name: v.name,
    cost: state.maintenance.filter(m => m.vehicle === v.id).reduce((s,m) => s + Number(m.cost), 0)
  })).filter(d => d.cost > 0);

  if (!data.length) {
    ctx.fillStyle = '#4a5270'; ctx.font = '14px Outfit, sans-serif';
    ctx.textAlign = 'center'; ctx.fillText('No maintenance data', W/2, H/2); return;
  }

  const maxV  = Math.max(...data.map(d => d.cost));
  const padL  = 140, padB = 30, padT = 20, padR = 30;
  const cW = W - padL - padR, cH = H - padB - padT;
  const rowH = cH / data.length;

  data.forEach((d, i) => {
    const y   = padT + rowH * i + rowH * 0.2;
    const bH  = rowH * 0.6;
    const bW  = (d.cost / maxV) * cW;

    const grad = ctx.createLinearGradient(padL, 0, padL + cW, 0);
    grad.addColorStop(0, '#6c63ff');
    grad.addColorStop(1, '#a78bfa');

    ctx.fillStyle = grad;
    ctx.beginPath(); ctx.roundRect(padL, y, bW, bH, 5); ctx.fill();

    ctx.fillStyle = '#8892b0'; ctx.font = '12px Outfit, sans-serif'; ctx.textAlign = 'right';
    ctx.fillText(d.name.length > 16 ? d.name.slice(0,16)+'…' : d.name, padL - 8, y + bH/2 + 4);

    ctx.fillStyle = '#e8eaf6'; ctx.font = 'bold 11px Outfit, sans-serif'; ctx.textAlign = 'left';
    ctx.fillText(fmtPKR(d.cost), padL + bW + 6, y + bH/2 + 4);
  });
  ctx.textAlign = 'left';
}

function drawTypeChart() {
  const canvas = document.getElementById('typeChart');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const W = canvas.width, H = canvas.height;
  ctx.clearRect(0, 0, W, H);

  const types = ['Car','Truck','Van','Motorcycle','Bus'];
  const colors = ['#6c63ff','#22c55e','#f97316','#3b82f6','#a855f7'];
  const counts = types.map(t => state.vehicles.filter(v => v.type === t).length);
  const maxV   = Math.max(...counts, 1);

  const padL = 120, padB = 30, padT = 20, padR = 30;
  const cW = W - padL - padR, cH = H - padB - padT;
  const rowH = cH / types.length;

  types.forEach((t, i) => {
    const y  = padT + rowH * i + rowH * 0.2;
    const bH = rowH * 0.6;
    const bW = (counts[i] / maxV) * cW;

    ctx.fillStyle = colors[i] + '33';
    ctx.beginPath(); ctx.roundRect(padL, y, cW, bH, 5); ctx.fill();

    ctx.fillStyle = colors[i];
    ctx.beginPath(); ctx.roundRect(padL, y, bW || 4, bH, 5); ctx.fill();

    ctx.fillStyle = '#8892b0'; ctx.font = '12px Outfit, sans-serif'; ctx.textAlign = 'right';
    ctx.fillText(t, padL - 8, y + bH/2 + 4);

    ctx.fillStyle = '#e8eaf6'; ctx.font = 'bold 12px Outfit, sans-serif'; ctx.textAlign = 'left';
    ctx.fillText(counts[i] + (counts[i]===1?' vehicle':' vehicles'), padL + Math.max(bW,4) + 6, y + bH/2 + 4);
  });
  ctx.textAlign = 'left';
}

