// ─── M-TAG ───────────────────────────────────────────────────────────────────

function renderMTag() {
  if (!state.mtag) state.mtag = [];
  const search = (document.getElementById('mtagSearch')?.value || '').toLowerCase();
  const typeFilter = document.getElementById('mtagTypeFilter')?.value || '';
  const tbody = document.getElementById('mtagBody');
  if (!tbody) return;

  // Populate Month Filter Dropdown
  const monthSel = document.getElementById('mtagMonthSelect');
  let selectedMonth = 'all';
  if (monthSel) {
    const prevVal = monthSel.value;
    const MONTH_NAMES = ['January','February','March','April','May','June','July','August','September','October','November','December'];
    const now = new Date();
    const curMonthKey = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`;
    const curMonthName = MONTH_NAMES[now.getMonth()];
    const curYear = now.getFullYear();

    const monthSet = new Set();
    monthSet.add(curMonthKey); // always include current month
    state.mtag.forEach(m => {
      if (m.date) {
        const d = new Date(m.date);
        if (!isNaN(d.getTime())) {
          monthSet.add(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`);
        }
      }
    });
    const allMonths = [...monthSet].sort().reverse();
    
    // Always include current month first, then "All Months", then rest
    let optionsHtml = `<option value="${curMonthKey}">📅 Current Month (${curMonthName} ${curYear})</option>`;
    optionsHtml += `<option value="all">📁 All Months (Full History)</option>`;

    allMonths.forEach(m => {
      if (m === curMonthKey) return; // already added above
      const [y, mo] = m.split('-');
      const mName = MONTH_NAMES[parseInt(mo, 10) - 1];
      let count = 0;
      state.mtag.forEach(entry => {
          if (entry.date && entry.date.startsWith(m)) {
              count += (entry.vehicles || []).length;
          }
      });
      optionsHtml += `<option value="${m}">📅 ${mName} ${y} (${count} entries)</option>`;
    });
    monthSel.innerHTML = optionsHtml;
    
    if (prevVal === 'all' || allMonths.includes(prevVal)) {
      monthSel.value = prevVal;
      selectedMonth = prevVal;
    } else if (allMonths.length > 0 && prevVal !== 'all') {
      monthSel.value = allMonths[0];
      selectedMonth = allMonths[0];
    }
  }

  // Flatten all vehicle rows from all M-Tag entries for display
  let rows = [];
  state.mtag.forEach(entry => {
    // Apply Month Filter
    if (selectedMonth !== 'all' && !(entry.date && entry.date.startsWith(selectedMonth))) return;
    
    (entry.vehicles || []).forEach((v, vi) => {
      if (typeFilter && v.vehicleType !== typeFilter) return;
      if (search && !(v.plate || '').toLowerCase().includes(search) &&
          !(v.accountNo || '').toLowerCase().includes(search) &&
          !(v.assign || '').toLowerCase().includes(search) &&
          !(entry.billNo || '').toLowerCase().includes(search) &&
          !(entry.period || '').toLowerCase().includes(search)) return;
      rows.push({ ...v, billNo: entry.billNo, billDate: entry.date, period: entry.period, status: entry.status, vendor: entry.vendor, entryId: entry.id, rowIdx: vi, grandTotal: entry.grandTotal });
    });
  });

  if (rows.length === 0) {
    const selText = monthSel ? (monthSel.options[monthSel.selectedIndex]?.text || '') : '';
    tbody.innerHTML = `<tr><td colspan="10" style="text-align:center;padding:32px;color:var(--text-muted);">
      No M-Tag entries found for <strong>${selText}</strong>.<br>
      <small>Select "📁 All Months (Full History)" from the dropdown above to see all records, or click "+ Add M-Tag Entry" to add new.</small>
    </td></tr>`;
    return;
  }

  tbody.innerHTML = rows.map((r, i) => {
    const typeColor = r.vehicleType === 'Admin' ? '#3b82f6' : '#8b5cf6';
    const statusColor = (r.status === 'Paid') ? '#16a34a' : '#d97706';
    const statusLabel = r.status || 'Pending';
    return `<tr>
      <td>${i + 1}</td>
      <td><span style="background:${typeColor};color:#fff;padding:2px 10px;border-radius:12px;font-size:0.82rem;">${r.vehicleType || '—'}</span></td>
      <td><strong>${r.plate || '—'}</strong></td>
      <td>${r.model || '—'}</td>
      <td>${r.assign || '—'}</td>
      <td><code style="background:var(--card);padding:2px 8px;border-radius:6px;">${r.accountNo || '—'}</code></td>
      <td><strong style="color:#22c55e;">PKR ${Number(r.topup || 0).toLocaleString()}</strong></td>
      <td>${r.billDate || '—'}</td>
      <td>
        <button class="btn-icon-sm" onclick="editMTagEntry('${r.entryId}')" title="Edit">✏️</button>
        <button class="btn-icon-sm" onclick="deleteMTagEntry('${r.entryId}')" title="Delete" style="color:#ef4444;">🗑️</button>
      </td>
    </tr>`;
  }).join('');
}

// M-Tag page table columns are now: SR, Type, Reg No, Model, Driver, Acc No, Toll, Top-up, Date, Actions
// Update the page table headers to match
(function updateMTagTableHeaders() {
  const thead = document.querySelector('#mtagTable thead tr');
  if (thead) {
    thead.innerHTML = `<th>SR</th><th>Vehicle Type</th><th>Reg No</th><th>Model / Make</th><th>Details</th><th>M-Tag Account No</th><th>Top-up (PKR)</th><th>Date</th><th>Actions</th>`;
  }
})();

let _mtagRowCounter = 0;

function addMTagVehicleRow(data) {
  _mtagRowCounter++;
  const tbody = document.getElementById('mtagVehicleRows');
  if (!tbody) return;
  const idx = _mtagRowCounter;
  const tr = document.createElement('tr');
  tr.id = 'mtagRow_' + idx;
  tr.innerHTML = `
    <td><select name="mtagRowType_${idx}" style="width:90px;padding:4px;" onchange="onMTagRowTypeChange(${idx})">
      <option value="Admin" ${(data?.vehicleType||'Admin')==='Admin'?'selected':''}>Admin</option>
      <option value="Sale" ${(data?.vehicleType)==='Sale'?'selected':''}>Sale</option>
    </select></td>
    <td><input type="text" name="mtagRowPlate_${idx}" style="width:100px;padding:4px;" value="${data?.plate||''}" placeholder="Plate No" /></td>
    <td><input type="text" name="mtagRowModel_${idx}" style="width:100px;padding:4px;" value="${data?.model||''}" placeholder="Model" /></td>
    <td><input type="text" name="mtagRowAssign_${idx}" style="width:100px;padding:4px;" value="${data?.assign||''}" placeholder="Details" /></td>
    <td><input type="text" name="mtagRowAccNo_${idx}" style="width:100px;padding:4px;" value="${data?.accountNo||''}" placeholder="Acc No" /></td>
    <td><input type="number" name="mtagRowTopup_${idx}" style="width:80px;padding:4px;" value="${data?.topup||''}" placeholder="0" min="0" oninput="updateMTagTotals()" /></td>
    <td style="text-align:center;"><button type="button" onclick="removeMTagRow(${idx})" style="background:none;border:none;color:#ef4444;cursor:pointer;font-size:1.1rem;">✕</button></td>
  `;
  tbody.appendChild(tr);
  updateMTagTotals();
}

function removeMTagRow(idx) {
  const row = document.getElementById('mtagRow_' + idx);
  if (row) row.remove();
  updateMTagTotals();
}

function updateMTagTotals() {
  let totalToll = 0, totalTopup = 0;
  document.querySelectorAll('#mtagVehicleRows tr').forEach(tr => {
    const tollInput = tr.querySelector('input[name^="mtagRowToll"]');
    const topupInput = tr.querySelector('input[name^="mtagRowTopup"]');
    if (tollInput) totalToll += Number(tollInput.value) || 0;
    if (topupInput) totalTopup += Number(topupInput.value) || 0;
  });
  const tollEl = document.getElementById('mtagTotalToll');
  const topupEl = document.getElementById('mtagTotalTopup');
  const grandEl = document.getElementById('mtagGrandTotal');
  if (tollEl) tollEl.textContent = 'PKR ' + totalToll.toLocaleString();
  if (topupEl) topupEl.textContent = 'PKR ' + totalTopup.toLocaleString();
  if (grandEl) grandEl.textContent = 'PKR ' + (totalToll + totalTopup).toLocaleString();
}

function getMTagVehicleRows() {
  const rows = [];
  document.querySelectorAll('#mtagVehicleRows tr').forEach(tr => {
    const id = tr.id.replace('mtagRow_', '');
    const vehicleType = tr.querySelector(`select[name="mtagRowType_${id}"]`)?.value || 'Admin';
    const plate = tr.querySelector(`input[name="mtagRowPlate_${id}"]`)?.value.trim() || '';
    const model = tr.querySelector(`input[name="mtagRowModel_${id}"]`)?.value.trim() || '';
    const assign = tr.querySelector(`input[name="mtagRowAssign_${id}"]`)?.value.trim() || '';
    const accountNo = tr.querySelector(`input[name="mtagRowAccNo_${id}"]`)?.value.trim() || '';
    const toll = Number(tr.querySelector(`input[name="mtagRowToll_${id}"]`)?.value) || 0;
    const topup = Number(tr.querySelector(`input[name="mtagRowTopup_${id}"]`)?.value) || 0;
    if (plate || accountNo) rows.push({ vehicleType, plate, model, assign, accountNo, toll, topup });
  });
  return rows;
}

function openMTagModal(id) {
  if (!state.mtag) state.mtag = [];
  document.getElementById('mtagForm').reset();
  document.getElementById('mtagEditId').value = '';
  document.getElementById('mtagModalTitle').textContent = 'Add M-Tag Entry';
  document.getElementById('mtagBillDate').value = new Date().toISOString().split('T')[0];
  document.getElementById('mtagVehicleRows').innerHTML = '';
  _mtagRowCounter = 0;

  if (id) {
    const entry = state.mtag.find(e => e.id === id);
    if (entry) {
      document.getElementById('mtagModalTitle').textContent = 'Edit M-Tag Entry';
      document.getElementById('mtagEditId').value = entry.id;
      document.getElementById('mtagBillNo').value = entry.billNo || '';
      document.getElementById('mtagBillDate').value = entry.date || '';
      document.getElementById('mtagVendor').value = entry.vendor || '';
      document.getElementById('mtagPeriod').value = entry.period || '';
      document.getElementById('mtagBillStatus').value = entry.status || 'Pending';
      document.getElementById('mtagNotes').value = entry.notes || '';
      (entry.vehicles || []).forEach(v => addMTagVehicleRow(v));
    }
  } else {
    // Auto bill number
    const mtagCount = (state.mtag || []).length + 1;
    document.getElementById('mtagBillNo').value = 'MT-' + new Date().getFullYear() + '-' + String(mtagCount).padStart(3, '0');
    addMTagVehicleRow(); // Start with one empty row
  }
  openModal('mtagModal');
}

function editMTagEntry(id) {
  openMTagModal(id);
}

function deleteMTagEntry(id) {
  if (!confirm('Are you sure you want to delete this M-Tag entry and its bill?')) return;
  state.mtag = (state.mtag || []).filter(e => e.id !== id);
  // Also remove associated bill
  if (state.bills) {
    state.bills = state.bills.filter(b => b.mtagEntryId !== id);
  }
  saveState();
  renderMTag();
  updateDashStats();
  if (document.getElementById('page-bills')?.classList.contains('active')) renderBills();
  showToast('M-Tag entry & bill deleted.', 'success');
}

function onMTagRowTypeChange(idx) {
  // Placeholder for future vehicle filtering per row
}

document.getElementById('mtagForm').addEventListener('submit', e => {
  e.preventDefault();
  if (!state.mtag) state.mtag = [];
  if (!state.bills) state.bills = [];

  const editId = document.getElementById('mtagEditId').value;
  const vehicles = getMTagVehicleRows();

  if (vehicles.length === 0) {
    showToast('Please add at least one vehicle row!', 'error');
    return;
  }

  const totalToll = vehicles.reduce((s, v) => s + v.toll, 0);
  const totalTopup = vehicles.reduce((s, v) => s + v.topup, 0);
  const grandTotal = totalToll + totalTopup;

  const entry = {
    id:       editId || uid(),
    billNo:   document.getElementById('mtagBillNo').value.trim(),
    date:     document.getElementById('mtagBillDate').value,
    vendor:   document.getElementById('mtagVendor').value.trim(),
    period:   document.getElementById('mtagPeriod').value.trim(),
    status:   document.getElementById('mtagBillStatus').value,
    notes:    document.getElementById('mtagNotes').value.trim(),
    vehicles: vehicles,
    totalToll: totalToll,
    totalTopup: totalTopup,
    grandTotal: grandTotal,
  };

  // Create/update bill in state.bills
  const bill = {
    id:           editId ? (state.bills.find(b => b.mtagEntryId === editId)?.id || uid()) : uid(),
    mtagEntryId:  entry.id,
    billNo:       entry.billNo,
    date:         entry.date,
    vehicle:      vehicles.map(v => v.plate).join(', '),
    type:         'M-Tag',
    vendor:       entry.vendor || 'M-Tag / Motorway',
    vendorAddress: '',
    amount:       grandTotal,
    status:       entry.status,
    notes:        entry.notes + (entry.period ? ' | Period: ' + entry.period : ''),
    currentReading: '',
    nextReading: '',
  };

  if (editId) {
    state.mtag = state.mtag.map(x => x.id === editId ? entry : x);
    const existingBillIdx = state.bills.findIndex(b => b.mtagEntryId === editId);
    if (existingBillIdx >= 0) {
      bill.id = state.bills[existingBillIdx].id;
      state.bills[existingBillIdx] = bill;
    } else {
      state.bills.push(bill);
    }
    showToast('M-Tag entry & bill updated! 🏷️', 'success');
  } else {
    state.mtag.push(entry);
    state.bills.push(bill);
    showToast('M-Tag entry saved & bill generated! 🏷️✅', 'success');
  }

  saveState();
  renderMTag();
  updateDashStats();
  if (document.getElementById('page-bills')?.classList.contains('active')) renderBills();
  closeModal('mtagModal');
});

// ─── ACCOUNTS / LEDGER ────────────────────────────────────────────────────────

function renderLedger() {
  if (!state.ledger) state.ledger = [];
  const MONTH_NAMES = ['January','February','March','April','May','June','July','August','September','October','November','December'];
  const now = new Date();
  const curMonthKey = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`;
  const curMonthName = MONTH_NAMES[now.getMonth()];
  const curYear = now.getFullYear();

  // Sort ALL records chronologically first to calculate running balance accurately
  const allChronological = [...state.ledger].sort((a, b) => new Date(a.date) - new Date(b.date));
  let runningCumBal = 0;
  allChronological.forEach(e => {
    const amt = Number(e.amount) || 0;
    if (e.type === 'Received') runningCumBal += amt;
    else if (e.type === 'Returned') runningCumBal -= amt;
    e._runningBal = runningCumBal;
  });

  // Calculate overall all-time totals
  const allTimeIn = allChronological.filter(e => e.type === 'Received').reduce((s, e) => s + (Number(e.amount) || 0), 0);
  const allTimeOut = allChronological.filter(e => e.type === 'Returned').reduce((s, e) => s + (Number(e.amount) || 0), 0);
  const allTimeBalance = allTimeIn - allTimeOut;

  // Build month set from all transactions + current month
  const monthSet = new Set();
  monthSet.add(curMonthKey);
  (state.ledger || []).forEach(e => {
    if (e.date) {
      const d = new Date(e.date);
      if (!isNaN(d.getTime())) {
        monthSet.add(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`);
      }
    }
  });
  const allMonths = [...monthSet].sort().reverse();

  // Populate month dropdown
  const monthSel = document.getElementById('ledgerMonthSelect');
  let selectedMonth = curMonthKey;
  if (monthSel) {
    const prevVal = monthSel.value;
    let optionsHtml = '';
    optionsHtml += `<option value="${curMonthKey}">📅 Current Month (${curMonthName} ${curYear})</option>`;
    optionsHtml += `<option value="all">📂 All Months (Full History)</option>`;

    allMonths.forEach(m => {
      if (m !== curMonthKey) {
        const [y, mo] = m.split('-');
        const mName = MONTH_NAMES[parseInt(mo, 10) - 1];
        const count = state.ledger.filter(e => e.date && e.date.startsWith(m)).length;
        optionsHtml += `<option value="${m}">📁 ${mName} ${y} (${count} entries)</option>`;
      }
    });

    monthSel.innerHTML = optionsHtml;
    if (prevVal && (prevVal === 'all' || allMonths.includes(prevVal))) {
      monthSel.value = prevVal;
      selectedMonth = prevVal;
    } else {
      // If current month has 0 entries but previous month has entries, default to current month (clean start)
      monthSel.value = curMonthKey;
      selectedMonth = curMonthKey;
    }
  }

  const search = (document.getElementById('ledgerSearch')?.value || '').toLowerCase();
  const typeFilter = document.getElementById('ledgerTypeFilter')?.value || '';
  const tbody = document.getElementById('ledgerBody');
  if (!tbody) return;

  // Calculate opening balance, period In, period Out, and closing balance
  let openingBal = 0;
  let periodEntries = [];
  let periodIn = 0;
  let periodOut = 0;
  let periodClosingBal = 0;
  let isAll = selectedMonth === 'all';
  let isCurrentMonth = selectedMonth === curMonthKey;
  let periodName = 'This Month';

  if (isAll) {
    periodName = 'All Time';
    openingBal = 0;
    periodEntries = allChronological;
    periodIn = allTimeIn;
    periodOut = allTimeOut;
    periodClosingBal = allTimeBalance;
  } else {
    const [y, mo] = selectedMonth.split('-');
    const mName = MONTH_NAMES[parseInt(mo, 10) - 1];
    periodName = isCurrentMonth ? `This Month (${mName} ${y})` : `${mName} ${y}`;

    // Opening Balance = Sum of all transactions before 1st of selectedMonth
    allChronological.forEach(e => {
      if (e.date && e.date < selectedMonth + '-01') {
        const amt = Number(e.amount) || 0;
        if (e.type === 'Received') openingBal += amt;
        else if (e.type === 'Returned') openingBal -= amt;
      }
    });

    periodEntries = allChronological.filter(e => e.date && e.date.startsWith(selectedMonth));
    periodIn = periodEntries.filter(e => e.type === 'Received').reduce((s, e) => s + (Number(e.amount) || 0), 0);
    periodOut = periodEntries.filter(e => e.type === 'Returned').reduce((s, e) => s + (Number(e.amount) || 0), 0);
    periodClosingBal = openingBal + periodIn - periodOut;
  }

  // Filter display entries by search & type
  let displayEntries = [...periodEntries];
  if (typeFilter) displayEntries = displayEntries.filter(e => e.type === typeFilter);
  if (search) displayEntries = displayEntries.filter(e =>
    (e.desc || '').toLowerCase().includes(search) ||
    (e.date || '').toLowerCase().includes(search)
  );

  // Sort descending (newest at top) for the table
  displayEntries.sort((a, b) => new Date(b.date) - new Date(a.date));

  // Build Table HTML
  let rowsHtml = '';

  // 1. Opening Balance Row (Shown when a specific month is selected)
  if (!isAll && !typeFilter && !search) {
    const opSign = openingBal >= 0 ? '+' : '-';
    rowsHtml += `
      <tr style="background:#f8fafc; font-weight:700; border-bottom:2px solid #cbd5e1;">
        <td style="text-align:center; color:#64748b;">📌</td>
        <td style="color:#64748b; font-size:0.88rem;">${selectedMonth}-01</td>
        <td><span style="background:#475569; color:#fff; padding:2px 8px; border-radius:10px; font-size:0.75rem; font-weight:700;">🏛️ Opening</span></td>
        <td style="color:#334155;"><strong>Opening Balance</strong> <span style="font-size:0.8rem; color:#64748b;">(Carried forward from previous months)</span></td>
        <td style="text-align:right; color:${openingBal >= 0 ? '#15803d' : '#b91c1c'}; font-weight:800; font-size:0.95rem;">
          ${opSign} PKR ${Math.abs(openingBal).toLocaleString()}
        </td>
        <td style="text-align:right; font-weight:800; color:#1e3a8a; font-size:1.02rem;">
          PKR ${openingBal.toLocaleString()}
        </td>
        <td style="text-align:center; color:#94a3b8;">—</td>
      </tr>
    `;
  }

  // 2. Transaction Rows
  if (displayEntries.length > 0) {
    rowsHtml += displayEntries.map((e, i) => {
      const typeColor = e.type === 'Received' ? '#22c55e' : '#f59e0b';
      const typeLabel = e.type === 'Received' ? '📥 In' : '📤 Out';
      const pending = Number(e.pendingAmt) || 0;
      const rowBg = pending > 0 ? 'background:rgba(239,68,68,0.07); border-left:4px solid #ef4444;' : '';
      const pendingBadge = pending > 0
        ? `<span style="background:#fef3c7; color:#b45309; border:1px solid #f59e0b; padding:2px 8px; border-radius:10px; font-size:0.78rem; font-weight:700; margin-left:6px;">⚠️ Pending: PKR ${pending.toLocaleString()}</span>`
        : '';
      const totalBillNote = Number(e.totalBill) > 0
        ? `<div style="font-size:0.78rem; color:#64748b; margin-top:2px;">Total Bill: PKR ${Number(e.totalBill).toLocaleString()}</div>`
        : '';
      const amtColor = e.type === 'Received' ? '#15803d' : '#d97706';
      const amtSign = e.type === 'Received' ? '+' : '-';

      return `
        <tr style="${rowBg}">
          <td style="text-align:center; font-weight:700; color:#64748b;">${i + 1}</td>
          <td style="font-weight:600; color:#1e293b;">${e.date || '—'}</td>
          <td><span style="background:${typeColor}; color:#fff; padding:2px 10px; border-radius:12px; font-size:0.8rem; font-weight:700;">${typeLabel}</span></td>
          <td>
            <div style="font-weight:600; color:#0f172a;">${e.desc || '—'}</div>
            ${pendingBadge}
            ${totalBillNote}
          </td>
          <td style="text-align:right; font-weight:800; color:${amtColor}; font-size:0.98rem;">
            ${amtSign} PKR ${Number(e.amount || 0).toLocaleString()}
          </td>
          <td style="text-align:right; font-weight:800; color:#1e3a8a; font-size:1rem;">
            PKR ${Number(e._runningBal || 0).toLocaleString()}
          </td>
          <td style="text-align:center;">
            <button class="btn-icon-sm" onclick="editLedgerEntry('${e.id}')" title="Edit">✏️</button>
            <button class="btn-icon-sm" onclick="deleteLedgerEntry('${e.id}')" title="Delete" style="color:#ef4444;">🗑️</button>
          </td>
        </tr>
      `;
    }).join('');
  } else {
    // Empty state message
    const emptyMsg = isCurrentMonth
      ? `No new transactions recorded for ${curMonthName} ${curYear} yet.`
      : `No transactions found for ${periodName}.`;

    rowsHtml += `
      <tr>
        <td colspan="7" style="text-align:center; padding:32px 20px; color:#64748b;">
          <div style="font-size:1.02rem; font-weight:700; color:#334155; margin-bottom:8px;">${emptyMsg}</div>
          <div style="font-size:0.9rem; color:#64748b;">
            Current Available Balance: <strong style="color:#1e3a8a; font-size:1rem;">PKR ${periodClosingBal.toLocaleString()}</strong>
            ${allMonths.length > 1 ? ` · <a href="javascript:void(0)" onclick="document.getElementById('ledgerMonthSelect').value='all';renderLedger();" style="color:#2563eb; font-weight:700; text-decoration:underline;">Click here to view All Months History</a>` : ''}
          </div>
        </td>
      </tr>
    `;
  }

  tbody.innerHTML = rowsHtml;

  // Update card labels
  const labelIn = document.getElementById('ledger-label-in');
  if (labelIn) labelIn.textContent = `${periodName} Received (In)`;
  const labelOut = document.getElementById('ledger-label-out');
  if (labelOut) labelOut.textContent = `${periodName} Returned (Out)`;
  const labelBalance = document.getElementById('ledger-label-balance');
  if (labelBalance) labelBalance.textContent = isAll ? 'Overall Net Balance' : `${periodName} Closing Balance`;

  // Update card values
  if (document.getElementById('ledger-total-in')) document.getElementById('ledger-total-in').textContent = 'PKR ' + periodIn.toLocaleString();
  if (document.getElementById('ledger-total-out')) document.getElementById('ledger-total-out').textContent = 'PKR ' + periodOut.toLocaleString();
  if (document.getElementById('ledger-balance')) {
    document.getElementById('ledger-balance').textContent = (periodClosingBal < 0 ? '- PKR ' + Math.abs(periodClosingBal).toLocaleString() : 'PKR ' + periodClosingBal.toLocaleString());
  }
  if (document.getElementById('ledger-total-balance')) {
    document.getElementById('ledger-total-balance').textContent = (allTimeBalance < 0 ? '- PKR ' + Math.abs(allTimeBalance).toLocaleString() : 'PKR ' + allTimeBalance.toLocaleString());
  }
}

function calcLedgerPending() {
  const amt = Number(document.getElementById('ledgerAmount')?.value) || 0;
  const total = Number(document.getElementById('ledgerTotalBill')?.value) || 0;
  const pendingEl = document.getElementById('ledgerPendingAmt');
  if (!pendingEl) return;
  if (total > 0 && amt >= 0) {
    const p = total - amt;
    pendingEl.value = p > 0 ? p : 0;
  } else {
    pendingEl.value = '';
  }
}

function openLedgerModal(id) {
  if (!state.ledger) state.ledger = [];
  document.getElementById('ledgerForm').reset();
  document.getElementById('ledgerEditId').value = '';
  document.getElementById('ledgerModalTitle').textContent = 'Add Transaction';
  document.getElementById('ledgerDate').value = new Date().toISOString().split('T')[0];

  if (id) {
    const entry = state.ledger.find(e => e.id === id);
    if (entry) {
      document.getElementById('ledgerModalTitle').textContent = 'Edit Transaction';
      document.getElementById('ledgerEditId').value = entry.id;
      document.getElementById('ledgerType').value = entry.type || 'Received';
      document.getElementById('ledgerDate').value = entry.date || '';
      document.getElementById('ledgerAmount').value = entry.amount || '';
      document.getElementById('ledgerDesc').value = entry.desc || '';
      if (document.getElementById('ledgerTotalBill')) document.getElementById('ledgerTotalBill').value = entry.totalBill || '';
      if (document.getElementById('ledgerPendingAmt')) document.getElementById('ledgerPendingAmt').value = entry.pendingAmt || '';
    }
  }
  openModal('ledgerModal');
}

